INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200001, 'HR_INTERVIEW', 'EASY', 'TEXT', 'Self Introduction', 'Tell me about yourself.', 'Cover your background, key skills, a project or achievement, and what you are looking for. Aim for 80 to 150 words.', 'A strong introduction is short and structured: who you are (education or experience), your main skills, one relevant project or achievement with a result, and why you want this role. Avoid reading your resume line by line and avoid personal details that are not relevant. Sample answer: I recently completed my Bachelor''s degree in Computer Science, where I focused on Java, SQL and web development. During my final year I built a full stack inventory system with Spring Boot and React that my department used to track lab equipment, and I completed a one-month internship where I worked with a team of five. I enjoy solving problems and learning quickly, and I am looking for a developer role where I can contribute to real products and keep growing.', TRUE);
INSERT INTO interview_rubric_concepts (id, question_id, name, keywords, weight, required, display_order) VALUES
  (1, 200001, 'Education or background', 'studied, degree, graduat, college, university, background, experience, completed', 2, TRUE, 1),
  (2, 200001, 'Key skills', 'skill, proficient, technolog, java, python, sql, react, tools, knowledge', 2, TRUE, 2),
  (3, 200001, 'A project or achievement', 'project, built, develop, internship, achieved, award, created', 2, TRUE, 3),
  (4, 200001, 'What you are looking for', 'looking for, seeking, goal, opportunity, want to, role, contribute', 1, FALSE, 4);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200001, 1), (200001, 2), (200001, 3), (200001, 4), (200001, 5), (200001, 6);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200002, 'HR_INTERVIEW', 'EASY', 'TEXT', 'Strengths', 'What are your greatest strengths?', 'Name two or three strengths that fit the role and back at least one with a real example.', 'Choose strengths that matter for the job, such as problem solving, learning quickly or teamwork, and prove them with a short example: what you did and what happened. A claim without an example sounds generic. Sample answer: My main strengths are problem solving and learning quickly. For example, in my final year project I had to use Spring Security without any prior experience. I read the documentation, built a small prototype in two days and then added login and roles to the project, which let us finish a week early. These strengths help me adapt to new tools and contribute to the team quickly in this role.', TRUE);
INSERT INTO interview_rubric_concepts (id, question_id, name, keywords, weight, required, display_order) VALUES
  (5, 200002, 'Names specific strengths', 'strength, good at, strong, skilled, quick learner, problem solving, adaptab, disciplin, communicat', 2, TRUE, 1),
  (6, 200002, 'Gives an example', 'for example, for instance, when i, in my project, once, i built, i led, example', 3, TRUE, 2),
  (7, 200002, 'Links to the job', 'role, job, team, company, helps me, useful, contribute, work', 2, TRUE, 3),
  (8, 200002, 'Shows impact', 'result, improv, success, delivered, saved, increased, helped', 1, FALSE, 4);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200002, 1), (200002, 2), (200002, 3), (200002, 4), (200002, 5), (200002, 6);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200003, 'HR_INTERVIEW', 'EASY', 'TEXT', 'Weaknesses', 'What is your biggest weakness?', 'Be honest, choose a real but manageable weakness and explain what you are doing to improve.', 'A good answer names a real weakness that is not essential for the job, shows that you understand its effect and describes concrete steps you are taking, with some progress. Avoid fake weaknesses such as ''I work too hard'' and avoid weaknesses that rule you out. Sample answer: My biggest weakness used to be that I spent too long perfecting small details, which sometimes slowed my team down. I realised this when a college project deadline almost slipped because I kept polishing one page. Since then I have been working on it by setting time limits for each task and asking a teammate for a quick review. On my last project I delivered all my tasks on time, and I still keep improving this habit.', TRUE);
INSERT INTO interview_rubric_concepts (id, question_id, name, keywords, weight, required, display_order) VALUES
  (9, 200003, 'Names a real weakness', 'weakness, struggle, difficult for me, used to, tend to, find it hard, improve on', 2, TRUE, 1),
  (10, 200003, 'Shows self-awareness', 'realised, realized, aware, noticed, learned that, understand that', 2, TRUE, 2),
  (11, 200003, 'Describes actions to improve', 'working on, improv, practi, course, learning, started, plan, habit, steps', 3, TRUE, 3),
  (12, 200003, 'Shows progress', 'now, progress, better, since then, result, already', 1, FALSE, 4);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200003, 1), (200003, 2), (200003, 3), (200003, 4), (200003, 5), (200003, 6);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200004, 'HR_INTERVIEW', 'EASY', 'TEXT', 'Motivation', 'Why should we hire you?', 'Match your skills and attitude to what the role needs and give evidence.', 'Show that you understand what the company needs and connect it to your skills, backed by a project or result. Mention your willingness to learn and to work in a team, and say what you will contribute. Do not criticise other candidates. Sample answer: You should hire me because my skills match this role and I learn quickly. I have strong knowledge of Java, SQL and React, and I built a project with these tools that handled over 200 records in daily use. I also work well in a team and I am willing to learn whatever the project needs. I will contribute by delivering clean, tested code and by helping the team meet its goals.', TRUE);
INSERT INTO interview_rubric_concepts (id, question_id, name, keywords, weight, required, display_order) VALUES
  (13, 200004, 'Skills that match the role', 'skill, experience, knowledge, technolog, qualif, match, fit', 3, TRUE, 1),
  (14, 200004, 'Evidence or example', 'project, built, example, internship, achieved, result, certificat', 2, TRUE, 2),
  (15, 200004, 'Learning attitude and teamwork', 'learn, team, adapt, quick, willing, collaborat, passion', 1, TRUE, 3),
  (16, 200004, 'What you will contribute', 'contribute, add value, help the team, bring, deliver, company, growth', 2, TRUE, 4);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200004, 1), (200004, 2), (200004, 3), (200004, 4), (200004, 5), (200004, 6);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200005, 'HR_INTERVIEW', 'EASY', 'TEXT', 'Career Goals', 'Where do you see yourself in five years?', 'Show realistic ambition that fits the role and the company. Mention skills you want to build.', 'Describe a realistic path: first learn the role and deliver well, then take on more responsibility such as becoming a senior developer or lead. Tie your goals to growth inside the company and to the skills you plan to build. Sample answer: In the first 12 months I want to learn the company''s technology, such as Java and Spring Boot, and deliver reliable work as part of the team. Over the next 3 to 5 years I want to grow into a senior developer who can design features and mentor new joiners. For example, I plan to earn an AWS certification and lead a small module. I hope to grow with a company like this one where I can take on more responsibility over time.', TRUE);
INSERT INTO interview_rubric_concepts (id, question_id, name, keywords, weight, required, display_order) VALUES
  (17, 200005, 'Realistic short-term goals', 'first year, short term, short-term, next few years, learn, master, grow as', 2, TRUE, 1),
  (18, 200005, 'Longer-term direction', 'five years, long term, long-term, senior, lead, architect, expert, responsib', 2, TRUE, 2),
  (19, 200005, 'Link to the company or role', 'company, organi, role, team, contribute, here', 2, TRUE, 3),
  (20, 200005, 'Plan to develop skills', 'skills, certificat, learn, mentor, course, improve', 1, FALSE, 4);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200005, 1), (200005, 2), (200005, 3), (200005, 4), (200005, 5), (200005, 6);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200006, 'HR_INTERVIEW', 'EASY', 'TEXT', 'Motivation', 'Why do you want to work in this role and for our company?', 'Show that you researched the company and explain your genuine interest in the role.', 'Show you did your homework: mention something specific about the company, such as its products, values or technology, and explain why the role matches your interests and skills. Generic answers about salary or location make a weak impression. Sample answer: I enjoy building software that people actually use, which is why this role interests me. I researched your company and I am excited by your products and your focus on quality and learning. My skills in Java and React fit the work, and I believe I can contribute quickly. I also see a great opportunity to learn from experienced engineers here and grow my career.', TRUE);
INSERT INTO interview_rubric_concepts (id, question_id, name, keywords, weight, required, display_order) VALUES
  (21, 200006, 'Interest in the role', 'interest, passion, enjoy, excited, fascinat, love', 2, TRUE, 1),
  (22, 200006, 'Knowledge of the company', 'company, product, mission, values, culture, technology, clients, known for, researched', 3, TRUE, 2),
  (23, 200006, 'How you fit', 'skills, fit, contribute, strengths, experience, align', 2, TRUE, 3),
  (24, 200006, 'Growth and learning', 'learn, grow, opportunit, challeng', 1, FALSE, 4);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200006, 1), (200006, 2), (200006, 3), (200006, 4), (200006, 5), (200006, 6);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200007, 'HR_INTERVIEW', 'EASY', 'TEXT', 'Motivation', 'Why did you choose a career in this field?', 'Tell a short, honest story about what attracted you and what you have done since.', 'Explain what first interested you, what you have done to build your skills (courses, projects, internships) and where you want to go. A specific story is more convincing than a general statement such as ''the field is in demand''. Sample answer: I became curious about programming in my second year when I built a small quiz application and enjoyed seeing people use it. Since then I have completed online courses, built three projects and finished an internship to build my skills. I want a career in software because the field keeps growing, there is always something new to learn and I can use technology to solve real problems.', TRUE);
INSERT INTO interview_rubric_concepts (id, question_id, name, keywords, weight, required, display_order) VALUES
  (25, 200007, 'What attracted you', 'interest, fascinat, curious, enjoy, inspired, passion, started', 2, TRUE, 1),
  (26, 200007, 'Steps you have taken', 'course, project, learn, practic, certificat, internship, built, studied', 3, TRUE, 2),
  (27, 200007, 'Future in the field', 'future, grow, career, goal, demand, opportunit', 2, TRUE, 3);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200007, 1), (200007, 2), (200007, 3), (200007, 4), (200007, 5), (200007, 6);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200008, 'HR_INTERVIEW', 'MEDIUM', 'TEXT', 'Teamwork', 'Describe a time you worked in a team and faced a challenge. How did you handle it?', 'Use the STAR method: Situation, Task, Action, Result. Say what YOU did.', 'Use the STAR structure: describe the team and the challenge, your specific actions (how you communicated and helped), the outcome and what you learned. Use I for your own contribution and we for the team''s result. Sample answer: In my final year project our team of four had a conflict about the database design a month before the deadline. My role was to coordinate the backend. I organised a meeting, listened to each person''s reasoning and suggested we compare both designs with a small test. We chose the simpler one, which reduced our query time by about 30 percent. We delivered on time and I learned to resolve disagreements with data.', TRUE);
INSERT INTO interview_rubric_concepts (id, question_id, name, keywords, weight, required, display_order) VALUES
  (28, 200008, 'Situation and task', 'team, project, situation, task, assignment, group, goal', 2, TRUE, 1),
  (29, 200008, 'Your actions', 'i decided, i organised, i organized, i suggested, i talked, i helped, i took, i created, my role, i proposed', 3, TRUE, 2),
  (30, 200008, 'Communication and collaboration', 'communicat, discuss, collaborat, listen, meeting, shared, agreed', 2, TRUE, 3),
  (31, 200008, 'Result and lesson', 'result, outcome, finished, delivered, completed, learned, successful, improved', 2, TRUE, 4);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200008, 1), (200008, 2), (200008, 3), (200008, 4), (200008, 5), (200008, 6);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200009, 'HR_INTERVIEW', 'MEDIUM', 'TEXT', 'Project Explanation', 'Explain a project you have worked on.', 'Cover the problem, your role, the technologies, one challenge you solved and the result.', 'Describe what the project does and why, your own responsibilities, the technologies and design choices, one real challenge and how you solved it, and the outcome or what you learned. Be ready for follow-up questions about any detail you mention. Sample answer: My main project was an inventory management system built to solve the problem of tracking lab equipment on paper. I was responsible for the backend, which I developed with Java, Spring Boot and MySQL, and I also helped with the React front end. The biggest challenge was slow search, which I solved by adding database indexes and pagination. As a result searches became about three times faster, and I learned a lot about performance and teamwork.', TRUE);
INSERT INTO interview_rubric_concepts (id, question_id, name, keywords, weight, required, display_order) VALUES
  (32, 200009, 'The problem and purpose', 'problem, purpose, objective, aim, goal, solves, built to', 2, TRUE, 1),
  (33, 200009, 'Your role and technologies', 'my role, i was responsible, i implemented, i developed, java, python, react, sql, spring, technolog, tools', 3, TRUE, 2),
  (34, 200009, 'A challenge and your solution', 'challenge, difficult, issue, bug, solved, fixed, overcame, optimi', 3, TRUE, 3),
  (35, 200009, 'Outcome', 'result, outcome, users, improved, deployed, completed, learned, feature', 2, TRUE, 4);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200009, 1), (200009, 2), (200009, 3), (200009, 4), (200009, 5), (200009, 6);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200010, 'HR_INTERVIEW', 'MEDIUM', 'TEXT', 'Pressure', 'How do you handle tight deadlines and pressure?', 'Describe a real situation and the steps you follow, such as prioritising and communicating early.', 'Explain a method: break the work into tasks, prioritise by importance, communicate early about risks, ask for help when needed and stay calm. Back it up with a real example in which you met a deadline, and mention what you learned. Sample answer: I prioritise tasks by importance, break the work into smaller steps and communicate early if there is a risk. For example, during my internship we had two days to finish a reporting feature. I listed the must-have parts, told my mentor which part might slip and focused on the core first. We delivered the main feature on time, and I stayed calm by taking one task at a time.', TRUE);
INSERT INTO interview_rubric_concepts (id, question_id, name, keywords, weight, required, display_order) VALUES
  (36, 200010, 'Prioritise tasks', 'prioriti, important first, urgent, plan, schedule, break down, breaking', 3, TRUE, 1),
  (37, 200010, 'Communicate early', 'communicat, inform, update, ask for help, tell the team, manager, stakeholder', 2, TRUE, 2),
  (38, 200010, 'Stay focused and calm', 'calm, focus, stay organised, stay organized, positive, avoid panic', 1, TRUE, 3),
  (39, 200010, 'Example and result', 'for example, deadline, once, when i, delivered, completed, on time', 2, TRUE, 4);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200010, 1), (200010, 2), (200010, 3), (200010, 4), (200010, 5), (200010, 6);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200011, 'HR_INTERVIEW', 'MEDIUM', 'TEXT', 'Feedback', 'Tell me about a time you received critical feedback. How did you react?', 'Show that you listen, act on feedback and learn from it. Use a real example.', 'Choose a real example. Show that you listened without getting defensive, asked questions if needed, took concrete action and improved. End with what you learned and how it helped later. Sample answer: During a code review on my college project, my mentor told me my methods were too long and hard to read. I listened carefully, thanked him and asked for examples. I then improved my code by splitting it into smaller methods and adding clear names. My next review had far fewer comments, and since then I always review my own code before submitting it.', TRUE);
INSERT INTO interview_rubric_concepts (id, question_id, name, keywords, weight, required, display_order) VALUES
  (40, 200011, 'A specific situation', 'feedback, review, manager, mentor, teacher, told me, pointed out, code review', 2, TRUE, 1),
  (41, 200011, 'Positive reaction', 'listened, thanked, accepted, understood, did not take it personally, open', 2, TRUE, 2),
  (42, 200011, 'Action taken', 'improved, changed, worked on, practiced, practised, fixed, applied, started', 3, TRUE, 3),
  (43, 200011, 'Result and lesson', 'result, better, learned, since then, improved, now', 2, TRUE, 4);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200011, 1), (200011, 2), (200011, 3), (200011, 4), (200011, 5), (200011, 6);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200012, 'HR_INTERVIEW', 'MEDIUM', 'TEXT', 'Learning', 'Tell me about a time you had to learn a new technology quickly.', 'Explain why, how you learned and what you achieved.', 'Describe the reason you had to learn something new, your learning plan (documentation, tutorials, a small practice project, asking others), what you built with it and what the experience taught you about learning fast. Sample answer: In my internship I needed to learn React in one week to help build a dashboard. I followed the official tutorial, practised by building a small to-do application and asked my mentor questions when I was stuck. By the end of the week I built two working components for the dashboard, and the result was that the team could demo on schedule. I learned that building something small is the fastest way to learn.', TRUE);
INSERT INTO interview_rubric_concepts (id, question_id, name, keywords, weight, required, display_order) VALUES
  (44, 200012, 'The need or situation', 'needed, required, project, deadline, new technology, new tool, assigned', 2, TRUE, 1),
  (45, 200012, 'How you learned', 'documentation, tutorial, course, practised, practiced, asked, mentor, youtube, built, experiment', 3, TRUE, 2),
  (46, 200012, 'What you achieved', 'built, completed, delivered, implemented, result, working, deployed', 2, TRUE, 3),
  (47, 200012, 'Lesson for the future', 'learned, approach, now i, confident, next time', 1, FALSE, 4);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200012, 1), (200012, 2), (200012, 3), (200012, 4), (200012, 5), (200012, 6);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200013, 'HR_INTERVIEW', 'MEDIUM', 'TEXT', 'Conflict', 'Tell me about a disagreement with a teammate and how you resolved it.', 'Stay professional: focus on the issue, not the person. Use STAR.', 'Describe the disagreement neutrally, show that you listened to the other view, explain how you reached a compromise or a decision based on facts, and say how the relationship and the result benefited. Never blame the other person. Sample answer: In a group project a teammate and I disagreed about using a framework for the front end. I listened to his perspective, explained my concern about the learning time and suggested we try both for 1 hour. For example, we built the same login page in React and Angular. We agreed on a compromise, using the framework he preferred with a simple structure I proposed. As a result we delivered on time with a score of 90 percent from our faculty, and I learned to focus on the problem, not the person.', TRUE);
INSERT INTO interview_rubric_concepts (id, question_id, name, keywords, weight, required, display_order) VALUES
  (48, 200013, 'The situation', 'disagree, conflict, different opinion, misunderstanding, teammate, colleague', 2, TRUE, 1),
  (49, 200013, 'Listening and communicating respectfully', 'listened, discussed, understand, perspective, respectful, calmly, talked', 3, TRUE, 2),
  (50, 200013, 'Finding a solution', 'compromise, agreed, solution, decided, data, tried both, common ground', 2, TRUE, 3),
  (51, 200013, 'Outcome and relationship', 'result, worked together, outcome, learned, relationship, moved forward', 2, TRUE, 4);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200013, 1), (200013, 2), (200013, 3), (200013, 4), (200013, 5), (200013, 6);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200014, 'HR_INTERVIEW', 'MEDIUM', 'TEXT', 'Time Management', 'How do you prioritise when you have several tasks at once?', 'Explain your method with an example.', 'Use a clear method such as listing tasks, ranking by urgency and impact, and clarifying priorities with your manager. Use a tool to track work and give a real example in which this helped you deliver on time. Sample answer: I list all tasks, rank them by urgency and impact and clarify priorities with my manager when needed. For example, in my last semester I had a project deadline, two exams and a lab report within the same week. I used a simple to-do list in Trello, started with the project and scheduled the exams around it. I completed everything on time and kept my results above 80 percent.', TRUE);
INSERT INTO interview_rubric_concepts (id, question_id, name, keywords, weight, required, display_order) VALUES
  (52, 200014, 'A clear method', 'urgent, important, priority, deadline, list, plan, matrix, impact', 3, TRUE, 1),
  (53, 200014, 'Communication with stakeholders', 'communicat, discuss, clarify, manager, team, expectations', 2, TRUE, 2),
  (54, 200014, 'Tools and organisation', 'todo, to-do, calendar, trello, jira, kanban, tracker, notes', 1, TRUE, 3),
  (55, 200014, 'Example', 'for example, once, when i, last semester, project, handled', 2, TRUE, 4);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200014, 1), (200014, 2), (200014, 3), (200014, 4), (200014, 5), (200014, 6);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200015, 'HR_INTERVIEW', 'HARD', 'TEXT', 'Failure', 'Describe a significant failure or mistake. What did you learn?', 'Choose a real mistake, take responsibility, and show what you changed afterwards.', 'Pick a genuine failure, explain the context, accept responsibility without excuses, describe how you fixed the situation and, most importantly, what you changed afterwards so it would not happen again. Sample answer: In my internship I once deployed a change without testing it on the staging server, and it broke the login page for about twenty minutes. It was my mistake and I took responsibility by informing my mentor immediately and rolling back the change. I then fixed the bug and wrote a deployment checklist. Since then I always test on staging first, and I learned that careful process prevents most problems.', TRUE);
INSERT INTO interview_rubric_concepts (id, question_id, name, keywords, weight, required, display_order) VALUES
  (56, 200015, 'A real mistake with context', 'mistake, failed, failure, went wrong, missed, error, did not work', 2, TRUE, 1),
  (57, 200015, 'Takes responsibility', 'my responsibility, i should have, i took, my mistake, i own, i accept, i realised, i realized', 3, TRUE, 2),
  (58, 200015, 'Corrective action', 'fixed, corrected, apologis, apologiz, recover, solved, informed, took steps', 3, TRUE, 3),
  (59, 200015, 'Lessons and changes', 'learned, lesson, now i, since then, changed, process, checklist, prevent', 3, TRUE, 4);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200015, 1), (200015, 2), (200015, 3), (200015, 4), (200015, 5), (200015, 6);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200016, 'HR_INTERVIEW', 'HARD', 'TEXT', 'Disagreement', 'Describe a time you disagreed with your manager or a senior colleague on a technical decision. What did you do?', 'Show respect, evidence and flexibility. Say what happened in the end.', 'Explain your concern calmly with evidence such as data or a small prototype, listen to the other side and accept the final decision even if it differs from yours. Close with the result and what you learned about influencing decisions respectfully. Sample answer: On my internship project my senior colleague wanted to store reports in a file system, but I was concerned about search performance. I explained my view politely with a small benchmark that showed MySQL was 5 times faster for search. He appreciated the data but chose the file system for now because of the deadline. I accepted the decision and supported it. As a result the release was on time, and after 2 months we moved to the database, which taught me to persuade with evidence.', TRUE);
INSERT INTO interview_rubric_concepts (id, question_id, name, keywords, weight, required, display_order) VALUES
  (60, 200016, 'The disagreement and your position', 'disagree, concern, different approach, my view, my opinion, suggested', 2, TRUE, 1),
  (61, 200016, 'Evidence and respectful communication', 'data, evidence, example, prototype, benchmark, respectful, politely, explained, asked questions', 3, TRUE, 2),
  (62, 200016, 'Willingness to commit to the decision', 'accepted, committed, supported, decision, agreed, final call, disagree and commit', 2, TRUE, 3),
  (63, 200016, 'Outcome and learning', 'result, outcome, learned, proved, later, worked out', 2, TRUE, 4);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200016, 1), (200016, 2), (200016, 3), (200016, 4), (200016, 5), (200016, 6);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200017, 'HR_INTERVIEW', 'HARD', 'TEXT', 'Ethics', 'You discover a serious bug in production just before a release deadline and your manager wants to ship anyway. What would you do?', 'Explain your reasoning: impact, communication, options and your decision.', 'First assess how severe the bug is and who it affects. Raise it immediately with evidence, and propose options such as a hotfix, a feature flag, a rollback or a short delay. Let the decision makers choose with full information, document it, and do not hide serious problems that could harm users. Sample answer: I would first assess the severity and who is affected, for example whether it could cause data loss or a security issue. Then I would inform my manager immediately with clear evidence and suggest options such as a quick hotfix, a feature flag or a short delay. If the risk to users is serious I would recommend not releasing, because quality and honesty matter more than one deadline. The final decision should be made with full information.', TRUE);
INSERT INTO interview_rubric_concepts (id, question_id, name, keywords, weight, required, display_order) VALUES
  (64, 200017, 'Assess severity and impact', 'severity, impact, risk, users affected, data loss, security, critical', 3, TRUE, 1),
  (65, 200017, 'Escalate and communicate transparently', 'inform, escalat, communicate, raise, tell, stakeholder, manager, transparent', 3, TRUE, 2),
  (66, 200017, 'Offer options', 'option, workaround, hotfix, rollback, delay, feature flag, fix quickly, mitigat', 2, TRUE, 3),
  (67, 200017, 'Integrity and quality', 'quality, honest, integrity, responsib, ethic, trust, customers', 2, TRUE, 4);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200017, 1), (200017, 2), (200017, 3), (200017, 4), (200017, 5), (200017, 6);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200018, 'HR_INTERVIEW', 'HARD', 'TEXT', 'Project Depth', 'Describe the most challenging project you have worked on: your role, key decisions, trade-offs and impact.', 'Go deeper than a summary: explain decisions, alternatives you rejected and measurable results.', 'A deep answer explains your responsibilities, the main design decisions and why you made them, the alternatives you considered and their trade-offs, and the measurable impact. Finish with what you would do differently. Sample answer: My most challenging project was a booking system for our college, where I was responsible for the backend design in a team of four. I decided to use Spring Boot with MySQL instead of a NoSQL database because the data was relational, and the trade-off was more schema planning. I also considered caching but chose indexes first to keep the system simple. As a result searches took under 200 ms for 5000 records, and next time I would add automated tests earlier.', TRUE);
INSERT INTO interview_rubric_concepts (id, question_id, name, keywords, weight, required, display_order) VALUES
  (68, 200018, 'Context and your role', 'my role, i was responsible, team of, project, owned, led', 2, TRUE, 1),
  (69, 200018, 'Key technical decisions', 'decided, chose, because, design, architecture, approach, technolog', 3, TRUE, 2),
  (70, 200018, 'Trade-offs and alternatives', 'trade-off, tradeoff, alternative, instead of, considered, pros and cons, compared', 3, TRUE, 3),
  (71, 200018, 'Impact and learning', 'impact, result, improved, reduced, increased, users, %, learned', 2, TRUE, 4);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200018, 1), (200018, 2), (200018, 3), (200018, 4), (200018, 5), (200018, 6);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200019, 'HR_INTERVIEW', 'HARD', 'TEXT', 'Leadership', 'Describe a time you led or influenced others without formal authority.', 'Show initiative, communication and results. Use STAR.', 'Describe a situation where you saw a need and took the lead without being the manager: how you convinced and motivated others, what actions you took and the result. Reflect on what you learned about leadership. Sample answer: In my third year our group had no clear plan for a hackathon project, so I took the initiative and proposed splitting the work into four parts. I explained the benefits, listened to concerns and encouraged each person to choose a task. As a result we delivered a working prototype in 24 hours and won second place. I learned that listening and clear communication matter more than titles when leading.', TRUE);
INSERT INTO interview_rubric_concepts (id, question_id, name, keywords, weight, required, display_order) VALUES
  (72, 200019, 'Taking initiative', 'initiative, volunteered, noticed, took the lead, proposed, started', 2, TRUE, 1),
  (73, 200019, 'Influencing with communication', 'convinc, persuad, explained, motivat, listened, aligned, encouraged', 3, TRUE, 2),
  (74, 200019, 'Delivering a result', 'result, delivered, completed, success, achieved, improved', 2, TRUE, 3),
  (75, 200019, 'Reflection', 'learned, next time, feedback, leadership', 1, FALSE, 4);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200019, 1), (200019, 2), (200019, 3), (200019, 4), (200019, 5), (200019, 6);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200020, 'HR_INTERVIEW', 'HARD', 'TEXT', 'Teamwork', 'How would you handle a teammate who repeatedly misses deadlines and affects your work?', 'Show empathy first, then clear communication, support and escalation only if needed.', 'Start with a private, respectful conversation to understand the cause, such as workload or blockers, and offer help. Agree on a plan with checkpoints and follow up. If the problem continues and affects the team, involve the manager with facts, not blame. Sample answer: I would first talk to the teammate privately to understand the reason, for example a heavy workload or a blocker, and offer help such as pair programming. Then we would agree on a plan with smaller tasks and regular checkpoints, and I would follow up each day. If the problem continued and affected the team, I would involve our manager with facts, not blame, and ask for support to reach a fair solution.', TRUE);
INSERT INTO interview_rubric_concepts (id, question_id, name, keywords, weight, required, display_order) VALUES
  (76, 200020, 'Talk to the teammate privately first', 'talk to, speak with, private, one-on-one, conversation, ask', 3, TRUE, 1),
  (77, 200020, 'Understand the reason and offer help', 'reason, understand, listen, offer help, support, workload, blocker, pair', 3, TRUE, 2),
  (78, 200020, 'Agree on a plan and follow up', 'plan, agree, checkpoint, follow up, break down, smaller', 2, TRUE, 3),
  (79, 200020, 'Escalate only if needed', 'escalat, manager, lead, if it continues, if nothing changes', 2, TRUE, 4);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200020, 1), (200020, 2), (200020, 3), (200020, 4), (200020, 5), (200020, 6);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200021, 'HR_INTERVIEW', 'HARD', 'TEXT', 'Integrity', 'Your manager asks you to take a shortcut that would reduce quality or break company rules. How do you respond?', 'Show professionalism, honesty and a constructive alternative.', 'Acknowledge the business pressure, explain the risks to quality, security or compliance calmly, and propose alternatives such as reducing scope or phasing the work. If the request is clearly unethical or against policy, politely refuse and escalate through proper channels. Sample answer: I would first understand the pressure and the reason behind the request, such as a deadline. Then I would explain the risks calmly, for example to security, quality or compliance, and suggest alternatives like reducing the scope or releasing in phases. If the request were clearly unethical or against company policy, I would politely refuse and escalate through the proper channel, because honesty and integrity matter to me and to the company.', TRUE);
INSERT INTO interview_rubric_concepts (id, question_id, name, keywords, weight, required, display_order) VALUES
  (80, 200021, 'Understand the pressure and the reason', 'understand, reason, deadline, pressure, business need, why', 2, TRUE, 1),
  (81, 200021, 'Explain risks respectfully', 'risk, consequence, quality, security, policy, rule, compliance, long term, long-term', 3, TRUE, 2),
  (82, 200021, 'Offer alternatives', 'alternative, option, compromise, phase, reduce scope, prioriti, suggest', 3, TRUE, 3),
  (83, 200021, 'Stand by ethical standards', 'ethic, integrity, honest, refuse, not comfortable, escalat, responsib', 2, TRUE, 4);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200021, 1), (200021, 2), (200021, 3), (200021, 4), (200021, 5), (200021, 6);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200022, 'TECHNICAL_MCQ', 'HARD', 'SINGLE_CHOICE', 'JVM and Memory', 'Which statement about the Java volatile keyword is correct?', NULL, 'volatile gives visibility and ordering guarantees only. Use synchronized, a lock or an AtomicInteger for atomic read-modify-write operations.', TRUE);
INSERT INTO interview_options (id, question_id, option_text, is_correct, display_order) VALUES
  (300001, 200022, 'It can only be applied to local variables', FALSE, 1),
  (300002, 200022, 'It guarantees visibility of writes between threads and prevents reordering around the access, but compound actions such as i++ are still not atomic', TRUE, 2),
  (300003, 200022, 'It locks the object so only one thread can use the variable', FALSE, 3),
  (300004, 200022, 'It makes i++ atomic and thread safe', FALSE, 4);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200022, 1);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200023, 'TECHNICAL_MCQ', 'HARD', 'SINGLE_CHOICE', 'Core Java Traps', 'What does this code print?
INSERT INTO interview_options (id, question_id, option_text, is_correct, display_order) VALUES
  (300005, 200023, 'true false', TRUE, 1),
  (300006, 200023, 'false true', FALSE, 2),
  (300007, 200023, 'true true', FALSE, 3),
  (300008, 200023, 'false false', FALSE, 4);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200023, 1);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200024, 'TECHNICAL_MCQ', 'HARD', 'SINGLE_CHOICE', 'Concurrency', 'How does ConcurrentHashMap differ from Collections.synchronizedMap(new HashMap<>())?', NULL, 'A synchronized wrapper serialises all access through one lock. ConcurrentHashMap lets non-conflicting operations proceed in parallel. It does not allow null keys or values.', TRUE);
INSERT INTO interview_options (id, question_id, option_text, is_correct, display_order) VALUES
  (300009, 200024, 'ConcurrentHashMap uses fine-grained locking and compare-and-swap so many threads can read and write at once, while synchronizedMap locks the whole map for every call', TRUE, 1),
  (300010, 200024, 'ConcurrentHashMap keeps keys sorted', FALSE, 2),
  (300011, 200024, 'They are identical in behaviour and speed', FALSE, 3),
  (300012, 200024, 'ConcurrentHashMap allows null keys and synchronizedMap does not', FALSE, 4);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200024, 1);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200025, 'TECHNICAL_MCQ', 'HARD', 'SINGLE_CHOICE', 'Garbage Collection', 'When is a Java object eligible for garbage collection?', NULL, 'The JVM uses reachability, not reference counting. System.gc() is only a hint.', TRUE);
INSERT INTO interview_options (id, question_id, option_text, is_correct, display_order) VALUES
  (300013, 200025, 'When the variable that referred to it goes out of the source file', FALSE, 1),
  (300014, 200025, 'When it is no longer reachable from any GC root such as a live thread stack or static field', TRUE, 2),
  (300015, 200025, 'As soon as its reference count reaches zero', FALSE, 3),
  (300016, 200025, 'Only after System.gc() is called', FALSE, 4);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200025, 1);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200026, 'TECHNICAL_MCQ', 'HARD', 'SINGLE_CHOICE', 'Generics', 'Why is the statement new T[10] not allowed for a type parameter T?', NULL, 'Generics are erased at compile time. Arrays need their element type at runtime, so generic array creation is rejected. Use a List<T> or cast an Object array.', TRUE);
INSERT INTO interview_options (id, question_id, option_text, is_correct, display_order) VALUES
  (300017, 200026, 'Because T must always be an interface', FALSE, 1),
  (300018, 200026, 'Because generic classes cannot have methods', FALSE, 2),
  (300019, 200026, 'Because arrays can only hold primitive types', FALSE, 3),
  (300020, 200026, 'Because of type erasure the runtime does not know T, so it cannot create or check an array of that type', TRUE, 4);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200026, 1);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200027, 'TECHNICAL_MCQ', 'HARD', 'SINGLE_CHOICE', 'Spring Transactions', 'In Spring, what happens when a method calls another @Transactional method of the same class (self-invocation)?', NULL, '@Transactional works through a proxy. Calls made inside the same object do not pass through the proxy. Move the method to another bean to get the transaction behaviour.', TRUE);
INSERT INTO interview_options (id, question_id, option_text, is_correct, display_order) VALUES
  (300021, 200027, 'Spring throws a compile error', FALSE, 1),
  (300022, 200027, 'The call goes directly to the method and bypasses the proxy, so the annotation on the called method is not applied', TRUE, 2),
  (300023, 200027, 'The outer transaction is rolled back automatically', FALSE, 3),
  (300024, 200027, 'Spring always starts a new transaction for the inner method', FALSE, 4);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200027, 1), (200027, 4);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200028, 'TECHNICAL_MCQ', 'HARD', 'SINGLE_CHOICE', 'Concurrency', 'What does the Global Interpreter Lock (GIL) in CPython imply for threads?', NULL, 'Use multiprocessing for CPU-bound work and threads or asyncio for I/O-bound work.', TRUE);
INSERT INTO interview_options (id, question_id, option_text, is_correct, display_order) VALUES
  (300025, 200028, 'Python cannot create threads at all', FALSE, 1),
  (300026, 200028, 'Every thread gets its own interpreter and memory', FALSE, 2),
  (300027, 200028, 'Only one thread executes Python bytecode at a time, so CPU-bound threads do not run in parallel, although I/O-bound threads still benefit', TRUE, 3),
  (300028, 200028, 'Threads run in parallel on all CPU cores without limits', FALSE, 4);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200028, 2);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200029, 'TECHNICAL_MCQ', 'HARD', 'SINGLE_CHOICE', 'Decorators', 'What does functools.wraps do inside a decorator?', NULL, 'Without wraps the decorated function would report the wrapper''s name and docstring, which breaks introspection and debugging.', TRUE);
INSERT INTO interview_options (id, question_id, option_text, is_correct, display_order) VALUES
  (300029, 200029, 'It caches the return value of the function', FALSE, 1),
  (300030, 200029, 'It makes the wrapped function run faster', FALSE, 2),
  (300031, 200029, 'It converts the function into a class', FALSE, 3),
  (300032, 200029, 'It copies metadata such as __name__ and __doc__ from the wrapped function to the wrapper', TRUE, 4);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200029, 2);
