INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200032, 'TECHNICAL_MCQ', 'HARD', 'SINGLE_CHOICE', 'OOP', 'For class D(B, C) where B(A) and C(A), what is the method resolution order of D?', NULL, 'Python uses C3 linearisation: each class appears before its parents and the order of the base classes is preserved.', TRUE);
