INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200033, 'TECHNICAL_MCQ', 'HARD', 'SINGLE_CHOICE', 'Data Model', 'After a = [[0] * 2] * 2 and a[0][0] = 1, what is a?', NULL, 'The outer multiplication repeats a reference to the same inner list, so both rows are one object.', TRUE);
