INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200034, 'TECHNICAL_MCQ', 'HARD', 'SINGLE_CHOICE', 'Async', 'What does await asyncio.gather(a(), b()) do?', NULL, 'gather schedules the coroutines together, which helps with I/O-bound work.', TRUE);
INSERT INTO interview_options (id, question_id, option_text, is_correct, display_order) VALUES
  (300049, 200034, 'Runs the coroutines in two separate processes', FALSE, 1),
  (300050, 200034, 'Cancels b() when a() finishes', FALSE, 2),
  (300051, 200034, 'Runs both coroutines concurrently on the event loop and returns their results in order', TRUE, 3),
  (300052, 200034, 'Runs a() to completion and only then starts b()', FALSE, 4);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200034, 2);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200035, 'TECHNICAL_MCQ', 'HARD', 'SINGLE_CHOICE', 'Memory', 'What is the purpose of __slots__ in a class?', NULL, 'Classes with many instances can save a lot of memory with __slots__, at the cost of flexibility.', TRUE);
INSERT INTO interview_options (id, question_id, option_text, is_correct, display_order) VALUES
  (300053, 200035, 'It makes the class immutable', FALSE, 1),
  (300054, 200035, 'It makes all attributes private', FALSE, 2),
  (300055, 200035, 'It enables multiple inheritance', FALSE, 3),
  (300056, 200035, 'It fixes the allowed attributes and avoids a per-instance __dict__, which saves memory', TRUE, 4);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200035, 2);
