INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200037, 'TECHNICAL_MCQ', 'HARD', 'SINGLE_CHOICE', 'Data Model', 'What is guaranteed about the iteration order of a dict in Python 3.7 and later?', NULL, 'Insertion order became part of the language specification in Python 3.7.', TRUE);
