INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200038, 'TECHNICAL_MCQ', 'HARD', 'SINGLE_CHOICE', 'Copying', 'Which statement about copy.deepcopy is correct?', NULL, 'A shallow copy shares nested objects with the original. A deep copy does not.', TRUE);
