INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200045, 'TECHNICAL_MCQ', 'EASY', 'SINGLE_CHOICE', 'JavaScript', 'Which array method removes the last element of an array and returns it?', NULL, 'pop removes and returns the last element. shift does the same for the first element and push adds to the end.', TRUE);
