INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200046, 'TECHNICAL_MCQ', 'EASY', 'SINGLE_CHOICE', 'JavaScript', 'Which operator compares both the value and the type of two operands in JavaScript?', NULL, '=== is the strict equality operator. == converts types before comparing.', TRUE);
