  (300099, 200046, '==', FALSE, 3),
  (300100, 200046, '!=', FALSE, 4);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200046, 3);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200047, 'TECHNICAL_MCQ', 'HARD', 'SINGLE_CHOICE', 'CSS Specificity', 'What is the specificity of the selector #nav .item a, written as (ids, classes, elements)?', NULL, 'One id (#nav), one class (.item) and one element (a) give (1, 1, 1).', TRUE);
INSERT INTO interview_options (id, question_id, option_text, is_correct, display_order) VALUES
  (300101, 200047, '(0, 1, 2)', FALSE, 1),
  (300102, 200047, '(1, 0, 2)', FALSE, 2),
  (300103, 200047, '(1, 1, 1)', TRUE, 3),
  (300104, 200047, '(0, 3, 0)', FALSE, 4);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200047, 3);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200048, 'TECHNICAL_MCQ', 'HARD', 'SINGLE_CHOICE', 'Event Loop', 'After the current synchronous code finishes, which callback runs first?', NULL, 'The event loop drains the microtask queue (promises) before it takes the next macrotask (timers).', TRUE);
INSERT INTO interview_options (id, question_id, option_text, is_correct, display_order) VALUES
  (300105, 200048, 'A resolved Promise callback (microtask) before a setTimeout(fn, 0) callback (macrotask)', TRUE, 1),
  (300106, 200048, 'Neither runs until the page is reloaded', FALSE, 2),
  (300107, 200048, 'The setTimeout callback, because its delay is 0', FALSE, 3),
  (300108, 200048, 'They always run in the order they were written', FALSE, 4);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200048, 3);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200049, 'TECHNICAL_MCQ', 'HARD', 'SINGLE_CHOICE', 'React Hooks', 'What does React''s useCallback hook return?', NULL, 'useCallback keeps the function identity stable, which helps child components that rely on referential equality.', TRUE);
INSERT INTO interview_options (id, question_id, option_text, is_correct, display_order) VALUES
  (300109, 200049, 'A memoised function that changes only when one of its dependencies changes', TRUE, 1),
  (300110, 200049, 'The result of calling the function', FALSE, 2),
  (300111, 200049, 'A new function on every render', FALSE, 3),
  (300112, 200049, 'A promise', FALSE, 4);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200049, 3);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200050, 'TECHNICAL_MCQ', 'HARD', 'SINGLE_CHOICE', 'React Rendering', 'Why is using the array index as a key problematic for lists that can be reordered or filtered?', NULL, 'Stable unique ids let React match old and new items correctly. Index keys are fine only for static lists.', TRUE);
INSERT INTO interview_options (id, question_id, option_text, is_correct, display_order) VALUES
  (300113, 200050, 'React may reuse the wrong component state or DOM node because the key no longer identifies the same item', TRUE, 1),
  (300114, 200050, 'Keys must always be strings', FALSE, 2),
  (300115, 200050, 'React throws an error when index keys are used', FALSE, 3),
  (300116, 200050, 'Index keys make the list render slower than any other key', FALSE, 4);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200050, 3);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200051, 'TECHNICAL_MCQ', 'HARD', 'SINGLE_CHOICE', 'Browser Security', 'What can cause a browser to send a CORS preflight (OPTIONS) request?', NULL, 'Simple requests skip the preflight. Requests with custom headers, JSON content type or methods such as PUT and DELETE trigger it.', TRUE);
INSERT INTO interview_options (id, question_id, option_text, is_correct, display_order) VALUES
  (300117, 200051, 'Loading an image from a CDN', FALSE, 1),
  (300118, 200051, 'Any request to the same origin', FALSE, 2),
  (300119, 200051, 'A cross-origin request that uses a non-simple method or header, for example PUT or an Authorization header', TRUE, 3),
  (300120, 200051, 'Using the GET method with no headers', FALSE, 4);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200051, 3), (200051, 4);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200052, 'TECHNICAL_MCQ', 'HARD', 'SINGLE_CHOICE', 'Closures', 'What does this code print?
INSERT INTO interview_options (id, question_id, option_text, is_correct, display_order) VALUES
  (300121, 200052, '2 2 2', FALSE, 1),
  (300122, 200052, '0 1 2', FALSE, 2),
  (300123, 200052, 'undefined undefined undefined', FALSE, 3),
  (300124, 200052, '3 3 3', TRUE, 4);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200052, 3);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200053, 'TECHNICAL_MCQ', 'HARD', 'SINGLE_CHOICE', 'Performance', 'Which Core Web Vital measures how long the largest visible content element takes to render?', NULL, 'LCP tracks loading performance. CLS measures visual stability and INP measures responsiveness.', TRUE);
INSERT INTO interview_options (id, question_id, option_text, is_correct, display_order) VALUES
  (300125, 200053, 'Cumulative Layout Shift (CLS)', FALSE, 1),
  (300126, 200053, 'Interaction to Next Paint (INP)', FALSE, 2),
  (300127, 200053, 'Time to Live (TTL)', FALSE, 3),
  (300128, 200053, 'Largest Contentful Paint (LCP)', TRUE, 4);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200053, 3);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200054, 'TECHNICAL_MCQ', 'HARD', 'SINGLE_CHOICE', 'Accessibility', 'What is the purpose of the aria-label attribute?', NULL, 'aria-label is useful for controls without visible text, such as an icon-only button.', TRUE);
INSERT INTO interview_options (id, question_id, option_text, is_correct, display_order) VALUES
  (300129, 200054, 'It gives an element an accessible name that assistive technologies can announce', TRUE, 1),
  (300130, 200054, 'It adds a CSS class', FALSE, 2),
  (300131, 200054, 'It makes the element focusable', FALSE, 3),
  (300132, 200054, 'It changes the visible text of the element', FALSE, 4);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200054, 3);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200055, 'TECHNICAL_MCQ', 'HARD', 'SINGLE_CHOICE', 'JavaScript Objects', 'What does Object.freeze(obj) do?', NULL, 'freeze is shallow. Nested objects can still be modified unless they are frozen too.', TRUE);
INSERT INTO interview_options (id, question_id, option_text, is_correct, display_order) VALUES
  (300133, 200055, 'It prevents adding, removing or changing the object''s own properties (shallowly)', TRUE, 1),
  (300134, 200055, 'It deep-freezes every nested object', FALSE, 2),
  (300135, 200055, 'It deletes all properties of the object', FALSE, 3),
  (300136, 200055, 'It only prevents the object from being garbage collected', FALSE, 4);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200055, 3);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200056, 'TECHNICAL_MCQ', 'HARD', 'SINGLE_CHOICE', 'CSS Layout', 'How does position: sticky behave?', NULL, 'sticky needs a threshold such as top: 0 and works inside its scrolling container.', TRUE);
INSERT INTO interview_options (id, question_id, option_text, is_correct, display_order) VALUES
  (300137, 200056, 'It behaves exactly like position: absolute', FALSE, 1),
  (300138, 200056, 'It is always fixed to the viewport', FALSE, 2),
  (300139, 200056, 'The element acts as relative until a scroll threshold is reached and then sticks like fixed within its container', TRUE, 3),
  (300140, 200056, 'It removes the element from the document flow', FALSE, 4);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200056, 3);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200057, 'TECHNICAL_MCQ', 'HARD', 'SINGLE_CHOICE', 'Security', 'Why should JWT access tokens have a short lifetime and be sent only over HTTPS?', NULL, 'Short expiry limits the damage of a stolen token and HTTPS protects it in transit. Use refresh tokens for longer sessions.', TRUE);
INSERT INTO interview_options (id, question_id, option_text, is_correct, display_order) VALUES
  (300141, 200057, 'JWTs stop working after one request', FALSE, 1),
  (300142, 200057, 'Short tokens are encrypted automatically', FALSE, 2),
  (300143, 200057, 'HTTPS makes the token smaller', FALSE, 3),
  (300144, 200057, 'A JWT is a bearer credential, so anyone who steals one can use it until it expires', TRUE, 4);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200057, 4);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200058, 'TECHNICAL_MCQ', 'HARD', 'SINGLE_CHOICE', 'ORM Performance', 'What is the N+1 query problem in an ORM such as Hibernate?', NULL, 'Lazy associations accessed in a loop cause one extra query per row. Fix it with join fetch, entity graphs or batch fetching.', TRUE);
INSERT INTO interview_options (id, question_id, option_text, is_correct, display_order) VALUES
  (300145, 200058, 'One query loads N parent rows and then N additional queries load the related data of each parent', TRUE, 1),
  (300146, 200058, 'A query with N+1 JOIN clauses', FALSE, 2),
  (300147, 200058, 'A database that has N+1 indexes', FALSE, 3),
  (300148, 200058, 'A query that returns N+1 duplicate rows', FALSE, 4);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200058, 4), (200058, 1);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200059, 'TECHNICAL_MCQ', 'HARD', 'SINGLE_CHOICE', 'Web Security', 'Which HTTP response header tells browsers to use only HTTPS for future visits to a site?', NULL, 'HSTS protects against protocol downgrade and cookie hijacking on plain HTTP.', TRUE);
INSERT INTO interview_options (id, question_id, option_text, is_correct, display_order) VALUES
  (300149, 200059, 'Access-Control-Allow-Origin', FALSE, 1),
  (300150, 200059, 'X-Frame-Options', FALSE, 2),
  (300151, 200059, 'Content-Security-Policy', FALSE, 3),
  (300152, 200059, 'Strict-Transport-Security', TRUE, 4);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200059, 4);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200060, 'TECHNICAL_MCQ', 'HARD', 'SINGLE_CHOICE', 'Advanced Testing', 'What is mutation testing?', NULL, 'If tests still pass after a mutation, they probably do not assert enough.', TRUE);
INSERT INTO interview_options (id, question_id, option_text, is_correct, display_order) VALUES
  (300153, 200060, 'Testing the application with mutated user data only', FALSE, 1),
  (300154, 200060, 'Testing software after it has been deployed', FALSE, 2),
  (300155, 200060, 'Introducing small deliberate changes (mutants) into the code to check whether the test suite detects them', TRUE, 3),
  (300156, 200060, 'Running the same test many times', FALSE, 4);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200060, 5);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200061, 'TECHNICAL_MCQ', 'HARD', 'SINGLE_CHOICE', 'Test Design', 'What is the goal of pairwise (all-pairs) testing?', NULL, 'Most defects are caused by one or two parameters interacting, so pairwise coverage finds many of them cheaply.', TRUE);
INSERT INTO interview_options (id, question_id, option_text, is_correct, display_order) VALUES
  (300157, 200061, 'Cover every pair of parameter values at least once with far fewer test cases than all combinations', TRUE, 1),
  (300158, 200061, 'Test two users at the same time', FALSE, 2),
  (300159, 200061, 'Compare two versions of the software', FALSE, 3),
  (300160, 200061, 'Run every test twice', FALSE, 4);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200061, 5);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200062, 'TECHNICAL_MCQ', 'HARD', 'SINGLE_CHOICE', 'Test Automation', 'What is a flaky test?', NULL, 'Flaky tests are often caused by timing, shared state or unstable environments, and they reduce trust in the suite.', TRUE);
INSERT INTO interview_options (id, question_id, option_text, is_correct, display_order) VALUES
  (300161, 200062, 'A test that always fails', FALSE, 1),
  (300162, 200062, 'A test that runs very slowly', FALSE, 2),
  (300163, 200062, 'A test written without assertions', FALSE, 3),
  (300164, 200062, 'A test that sometimes passes and sometimes fails without any change in the code', TRUE, 4);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200062, 5);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200063, 'TECHNICAL_MCQ', 'HARD', 'SINGLE_CHOICE', 'Test Strategy', 'What does the test automation pyramid recommend?', NULL, 'Lower-level tests are faster, cheaper and more stable than UI tests.', TRUE);
INSERT INTO interview_options (id, question_id, option_text, is_correct, display_order) VALUES
  (300165, 200063, 'The same number of tests at every level', FALSE, 1),
  (300166, 200063, 'Mostly UI tests with a few unit tests', FALSE, 2),
  (300167, 200063, 'Only manual tests at the top', FALSE, 3),
  (300168, 200063, 'Many fast unit tests, fewer integration tests and the fewest UI end-to-end tests', TRUE, 4);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200063, 5);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200064, 'TECHNICAL_MCQ', 'HARD', 'SINGLE_CHOICE', 'Performance Testing', 'How does stress testing differ from load testing?', NULL, 'Stress tests reveal how the system fails and recovers under extreme conditions.', TRUE);
INSERT INTO interview_options (id, question_id, option_text, is_correct, display_order) VALUES
  (300169, 200064, 'They are two names for the same thing', FALSE, 1),
  (300170, 200064, 'Load testing finds security issues and stress testing finds UI bugs', FALSE, 2),
  (300171, 200064, 'Load testing checks behaviour at expected usage, while stress testing pushes beyond it to find the breaking point', TRUE, 3),
  (300172, 200064, 'Stress testing uses fewer users than load testing', FALSE, 4);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200064, 5);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200065, 'TECHNICAL_MCQ', 'HARD', 'SINGLE_CHOICE', 'Quality Metrics', 'What is a risk of relying only on code coverage to judge test quality?', NULL, 'Coverage shows which code ran, not whether its behaviour was verified.', TRUE);
INSERT INTO interview_options (id, question_id, option_text, is_correct, display_order) VALUES
  (300173, 200065, 'High coverage can still come from tests with weak or no assertions, so defects may go unnoticed', TRUE, 1),
  (300174, 200065, 'Coverage lowers the number of tests', FALSE, 2),
  (300175, 200065, 'Coverage always slows down the application', FALSE, 3),
  (300176, 200065, 'Coverage cannot be measured automatically', FALSE, 4);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200065, 5);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200066, 'TECHNICAL_MCQ', 'HARD', 'SINGLE_CHOICE', 'Test Theory', 'What is a test oracle?', NULL, 'Examples are requirements, a reference implementation or a previous version of the output.', TRUE);
INSERT INTO interview_options (id, question_id, option_text, is_correct, display_order) VALUES
  (300177, 200066, 'A person who approves the release', FALSE, 1),
  (300178, 200066, 'A database of past defects', FALSE, 2),
  (300179, 200066, 'A tool that writes test cases automatically', FALSE, 3),
  (300180, 200066, 'A mechanism or source of truth used to decide whether a test result is correct', TRUE, 4);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200066, 5);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200067, 'TECHNICAL_MCQ', 'HARD', 'SINGLE_CHOICE', 'Statistics', 'What is Simpson''s paradox?', NULL, 'It occurs when a hidden variable affects group sizes, which is why you should check data by segment.', TRUE);
INSERT INTO interview_options (id, question_id, option_text, is_correct, display_order) VALUES
  (300181, 200067, 'A sample that is too small to analyse', FALSE, 1),
  (300182, 200067, 'An error in a correlation formula', FALSE, 2),
  (300183, 200067, 'Two variables always move in opposite directions', FALSE, 3),
  (300184, 200067, 'A trend that appears in several groups reverses or disappears when the groups are combined', TRUE, 4);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200067, 6);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200068, 'TECHNICAL_MCQ', 'HARD', 'SINGLE_CHOICE', 'SQL Window Functions', 'Which problem does the SQL window function LAG() help to solve?', NULL, 'LAG(column, n) returns the value from n rows before the current row within the partition.', TRUE);
INSERT INTO interview_options (id, question_id, option_text, is_correct, display_order) VALUES
  (300185, 200068, 'Comparing a row with a value from a previous row, for example month-over-month change', TRUE, 1),
  (300186, 200068, 'Encrypting a column', FALSE, 2),
  (300187, 200068, 'Joining two tables on a key', FALSE, 3),
  (300188, 200068, 'Removing duplicate rows', FALSE, 4);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200068, 6);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200069, 'TECHNICAL_INTERVIEW', 'EASY', 'TEXT', 'Statistics', 'Explain mean, median and mode. When is the median better than the mean?', NULL, 'The mean is the sum divided by the count, the median is the middle value of the sorted data and the mode is the most frequent value. The median is better when the data is skewed or has outliers, such as salaries, because extreme values pull the mean but barely change the median.', TRUE);
INSERT INTO interview_rubric_concepts (id, question_id, name, keywords, weight, required, display_order) VALUES
  (84, 200069, 'Mean is the average', 'mean, average, sum divided', 2, TRUE, 1),
  (85, 200069, 'Median is the middle value', 'median, middle', 2, TRUE, 2),
  (86, 200069, 'Mode is the most frequent value', 'mode, most frequent, most common', 1, TRUE, 3),
  (87, 200069, 'Median resists outliers', 'outlier, skew, extreme, salary, income', 2, TRUE, 4);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200069, 6);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200070, 'TECHNICAL_INTERVIEW', 'EASY', 'TEXT', 'Data Preparation', 'What steps do you take to clean a data set?', NULL, 'Inspect the data first, then remove duplicates, handle missing values by dropping or imputing them, fix data types and inconsistent formats (dates, text case, units), investigate outliers and validate against business rules. Document every change so the analysis is reproducible.', TRUE);
INSERT INTO interview_rubric_concepts (id, question_id, name, keywords, weight, required, display_order) VALUES
  (88, 200070, 'Remove duplicates', 'duplicate', 2, TRUE, 1),
  (89, 200070, 'Handle missing values', 'missing, null, impute, fill, drop', 2, TRUE, 2),
  (90, 200070, 'Fix types, formats and inconsistencies', 'format, data type, inconsisten, standardi, typo', 2, TRUE, 3),
  (91, 200070, 'Detect outliers and validate', 'outlier, validat, range, check', 1, FALSE, 4);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200070, 6);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200071, 'TECHNICAL_INTERVIEW', 'EASY', 'TEXT', 'SQL', 'Explain the different types of SQL joins.', NULL, 'INNER JOIN returns only rows with matches in both tables. LEFT JOIN returns all rows from the left table and matches from the right (NULL where there is none), RIGHT JOIN is the mirror image and FULL OUTER JOIN returns all rows from both. For example, a LEFT JOIN from customers to orders finds customers without orders.', TRUE);
INSERT INTO interview_rubric_concepts (id, question_id, name, keywords, weight, required, display_order) VALUES
  (92, 200071, 'INNER JOIN returns matching rows', 'inner join, matching, both tables', 2, TRUE, 1),
  (93, 200071, 'LEFT JOIN keeps all left rows', 'left join, left outer, all rows from the left', 2, TRUE, 2),
  (94, 200071, 'RIGHT and FULL joins', 'right join, full join, full outer', 2, TRUE, 3),
  (95, 200071, 'Example use', 'for example, customers, orders, no orders, null', 1, FALSE, 4);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200071, 6);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200072, 'TECHNICAL_INTERVIEW', 'EASY', 'TEXT', 'Tools', 'What is a pivot table and when would you use one?', NULL, 'A pivot table summarises large data sets by grouping fields into rows and columns and aggregating values (sum, count, average), with filters and slicers. It gives quick interactive analysis without writing formulas, for example sales by region and month.', TRUE);
INSERT INTO interview_rubric_concepts (id, question_id, name, keywords, weight, required, display_order) VALUES
  (96, 200072, 'Summarises data by categories', 'summar, aggregate, group, categor', 2, TRUE, 1),
  (97, 200072, 'Rows, columns, values and filters', 'rows, columns, values, filter', 2, TRUE, 2),
  (98, 200072, 'Quick analysis without formulas', 'quick, interactive, without formula, drag', 1, TRUE, 3),
  (99, 200072, 'Example', 'sales by region, per month, total, count', 1, FALSE, 4);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200072, 6);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200073, 'TECHNICAL_INTERVIEW', 'EASY', 'TEXT', 'Visualisation', 'How do you choose the right chart for your data?', NULL, 'Match the chart to the question: line charts for trends over time, bar charts to compare categories, pie charts only for a few parts of a whole, scatter plots for relationships between two numbers and histograms for distributions. Keep it simple, label clearly and avoid misleading scales.', TRUE);
INSERT INTO interview_rubric_concepts (id, question_id, name, keywords, weight, required, display_order) VALUES
  (100, 200073, 'Line charts for trends over time', 'line, trend, over time', 2, TRUE, 1),
  (101, 200073, 'Bar charts for comparisons', 'bar, column, compar', 2, TRUE, 2),
  (102, 200073, 'Pie charts for few parts of a whole', 'pie, part of a whole, proportion, share', 1, TRUE, 3),
  (103, 200073, 'Scatter plots and histograms', 'scatter, relationship, histogram, distribution', 2, FALSE, 4);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200073, 6);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200074, 'TECHNICAL_INTERVIEW', 'MEDIUM', 'TEXT', 'SQL', 'What is the difference between WHERE and HAVING, and how does GROUP BY work?', NULL, 'WHERE filters individual rows before they are grouped, while HAVING filters the groups produced by GROUP BY using aggregate conditions. For example, SELECT department, COUNT(*) FROM employees GROUP BY department HAVING COUNT(*) > 5 lists departments with more than five employees.', TRUE);
INSERT INTO interview_rubric_concepts (id, question_id, name, keywords, weight, required, display_order) VALUES
  (104, 200074, 'WHERE filters rows before grouping', 'where, before group, filters rows', 2, TRUE, 1),
  (105, 200074, 'HAVING filters groups after aggregation', 'having, after group, aggregate', 2, TRUE, 2),
  (106, 200074, 'GROUP BY forms groups for aggregates', 'group by, sum, count, avg, aggregate', 2, TRUE, 3),
  (107, 200074, 'Example', 'for example, department, more than, >', 1, FALSE, 4);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200074, 6);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200075, 'TECHNICAL_INTERVIEW', 'MEDIUM', 'TEXT', 'Data Quality', 'How do you handle missing values and outliers?', NULL, 'First understand why values are missing. Then drop, impute with the median or mean, or use a model depending on the amount and pattern. Detect outliers with the IQR rule, z-scores or box plots, and decide using domain knowledge whether they are errors to fix or genuine events to keep.', TRUE);
INSERT INTO interview_rubric_concepts (id, question_id, name, keywords, weight, required, display_order) VALUES
  (108, 200075, 'Understand why data is missing', 'why, reason, missing at random, mcar, cause', 2, TRUE, 1),
  (109, 200075, 'Impute or drop', 'impute, mean, median, drop, remove, fill', 2, TRUE, 2),
  (110, 200075, 'Detect outliers', 'iqr, z-score, z score, box plot, standard deviation', 2, TRUE, 3),
  (111, 200075, 'Decide using context', 'context, domain, error, genuine, business', 1, TRUE, 4);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200075, 6);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200076, 'TECHNICAL_INTERVIEW', 'MEDIUM', 'TEXT', 'Analytical Thinking', 'What is the difference between correlation and causation? Give an example.', NULL, 'Correlation means two variables move together. Causation means a change in one produces a change in the other. A third factor can explain a correlation: ice cream sales and drowning both rise in summer because of the temperature. Experiments such as A/B tests help show causation.', TRUE);
INSERT INTO interview_rubric_concepts (id, question_id, name, keywords, weight, required, display_order) VALUES
  (112, 200076, 'Correlation is a statistical relationship', 'correlation, relationship, move together, associat', 2, TRUE, 1),
  (113, 200076, 'Causation means one causes the other', 'causation, cause, effect, because', 2, TRUE, 2),
