INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200077, 'TECHNICAL_INTERVIEW', 'MEDIUM', 'TEXT', 'Reporting', 'How do you choose KPIs and design a dashboard for business users?', NULL, 'Start with the decisions users need to make and pick a small set of KPIs tied to business goals. Place the most important numbers at the top, use simple charts with filters, define each metric clearly and make sure the data is accurate and refreshed on a schedule.', TRUE);
INSERT INTO interview_rubric_concepts (id, question_id, name, keywords, weight, required, display_order) VALUES
  (116, 200077, 'Start from business goals', 'goal, objective, business question, stakeholder', 2, TRUE, 1),
  (117, 200077, 'Choose a few meaningful KPIs', 'kpi, metric, few, key', 2, TRUE, 2),
  (118, 200077, 'Clear layout and visuals', 'layout, chart, simple, filter, drill', 2, TRUE, 3),
  (119, 200077, 'Data freshness and definitions', 'refresh, definition, source, accura', 1, FALSE, 4);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200077, 6);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200078, 'TECHNICAL_INTERVIEW', 'MEDIUM', 'TEXT', 'Experimentation', 'Explain the basics of A/B testing.', NULL, 'In an A/B test users are randomly assigned to a control (A) and a variant (B). Define a hypothesis and a success metric in advance, run the test long enough with an adequate sample size, and use a significance test (p-value or confidence interval) to decide whether the difference is real.', TRUE);
INSERT INTO interview_rubric_concepts (id, question_id, name, keywords, weight, required, display_order) VALUES
  (120, 200078, 'Two variants, random assignment', 'variant, control, random, two groups, group a', 2, TRUE, 1),
  (121, 200078, 'Hypothesis and one metric', 'hypothesis, metric, null', 2, TRUE, 2),
  (122, 200078, 'Sample size and duration', 'sample size, duration, enough users, power', 2, TRUE, 3),
  (123, 200078, 'Statistical significance', 'significan, p-value, confidence', 2, TRUE, 4);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200078, 6);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200079, 'TECHNICAL_INTERVIEW', 'HARD', 'TEXT', 'SQL', 'Explain SQL window functions and give practical examples.', NULL, 'Window functions use OVER (PARTITION BY ... ORDER BY ...) to calculate values across related rows while keeping every row. Examples: ROW_NUMBER or RANK for top-N per group, LAG for month-over-month change and SUM() OVER for running totals.', TRUE);
INSERT INTO interview_rubric_concepts (id, question_id, name, keywords, weight, required, display_order) VALUES
  (124, 200079, 'Calculate across related rows without collapsing them', 'window, over, without collaps, partition', 2, TRUE, 1),
  (125, 200079, 'ROW_NUMBER, RANK and DENSE_RANK', 'row_number, rank, dense_rank', 2, TRUE, 2),
  (126, 200079, 'LAG and LEAD for comparisons', 'lag, lead, previous row, next row', 1, TRUE, 3),
  (127, 200079, 'Running totals and top-N per group', 'running total, cumulative, top n, per group, sum() over', 2, TRUE, 4);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200079, 6);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200080, 'TECHNICAL_INTERVIEW', 'HARD', 'TEXT', 'Process', 'Walk me through an end-to-end analysis project you would run, from question to recommendation.', NULL, 'Define the business question and success measure, collect data from reliable sources, clean and explore it, analyse and visualise to find patterns, validate assumptions, and finally present clear recommendations to stakeholders. Close the loop by tracking the outcome.', TRUE);
INSERT INTO interview_rubric_concepts (id, question_id, name, keywords, weight, required, display_order) VALUES
  (128, 200080, 'Define the business question', 'question, objective, goal, problem', 2, TRUE, 1),
  (129, 200080, 'Collect and clean the data', 'collect, source, clean, prepare', 2, TRUE, 2),
  (130, 200080, 'Analyse and visualise', 'analy, explor, visuali, model', 2, TRUE, 3),
  (131, 200080, 'Communicate recommendations', 'recommend, insight, stakeholder, present, action', 2, TRUE, 4),
  (132, 200080, 'Validate and iterate', 'validat, check, assumption, iterate', 1, FALSE, 5);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200080, 6);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200081, 'TECHNICAL_INTERVIEW', 'HARD', 'TEXT', 'Statistics', 'Explain p-values, confidence intervals and Type I and Type II errors.', NULL, 'A p-value is the probability of seeing data at least this extreme if the null hypothesis were true. A confidence interval gives a range of plausible values for the parameter. A Type I error is a false positive (rejecting a true null) and a Type II error is a false negative (missing a real effect).', TRUE);
INSERT INTO interview_rubric_concepts (id, question_id, name, keywords, weight, required, display_order) VALUES
  (133, 200081, 'p-value measures how surprising the data is under the null', 'p-value, null hypothesis, probability', 2, TRUE, 1),
  (134, 200081, 'Confidence interval gives a range of plausible values', 'confidence interval, range, plausible', 2, TRUE, 2),
  (135, 200081, 'Type I error is a false positive', 'type i, false positive, reject a true', 2, TRUE, 3),
  (136, 200081, 'Type II error is a false negative', 'type ii, false negative, miss, fail to reject', 2, TRUE, 4);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200081, 6);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200082, 'TECHNICAL_INTERVIEW', 'HARD', 'TEXT', 'SQL Performance', 'How do you optimise a slow SQL query?', NULL, 'Check the execution plan with EXPLAIN, add indexes on the columns used in filters and joins, avoid SELECT *, filter early, avoid functions on indexed columns and rewrite expensive subqueries or aggregate in stages. Re-measure after each change.', TRUE);
INSERT INTO interview_rubric_concepts (id, question_id, name, keywords, weight, required, display_order) VALUES
  (137, 200082, 'Look at the execution plan', 'explain, execution plan, query plan', 2, TRUE, 1),
  (138, 200082, 'Add suitable indexes', 'index', 2, TRUE, 2),
  (139, 200082, 'Select only what you need and filter early', 'select *, only needed, filter early, limit, where', 2, TRUE, 3),
  (140, 200082, 'Avoid expensive patterns', 'function on column, subquer, join order, temp table, aggregate', 1, FALSE, 4);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200082, 6);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200083, 'TECHNICAL_INTERVIEW', 'HARD', 'TEXT', 'Analytical Thinking', 'How do you make sure your analysis is correct and not misleading? Mention biases such as Simpson''s paradox.', NULL, 'Cross-check numbers against the source, sanity check totals and look at the data by segment, because a trend can reverse when groups are combined (Simpson''s paradox). Watch for selection bias and small samples, and document assumptions and limitations so others can reproduce and challenge the result.', TRUE);
INSERT INTO interview_rubric_concepts (id, question_id, name, keywords, weight, required, display_order) VALUES
  (141, 200083, 'Validate data and calculations', 'validat, reconcil, cross-check, sanity check, source', 2, TRUE, 1),
  (142, 200083, 'Segment the data', 'segment, subgroup, breakdown, simpson', 2, TRUE, 2),
  (143, 200083, 'Beware biases and small samples', 'bias, sample size, survivor, selection', 2, TRUE, 3),
  (144, 200083, 'Document assumptions', 'assumption, document, limitation, reproduc', 1, TRUE, 4);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200083, 6);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200084, 'TECHNICAL_INTERVIEW', 'EASY', 'TEXT', 'CSS', 'Explain the CSS box model.', NULL, 'Every element is a box made of content, padding, border and margin, from the inside out. With the default content-box, width applies to the content only and padding and border add to it. With box-sizing: border-box the width includes padding and border, which makes layouts easier to predict.', TRUE);
INSERT INTO interview_rubric_concepts (id, question_id, name, keywords, weight, required, display_order) VALUES
  (145, 200084, 'Content, padding, border and margin', 'content, padding, border, margin', 3, TRUE, 1),
  (146, 200084, 'Layers from inside to outside', 'inside, outside, around, layers, outer', 1, TRUE, 2),
  (147, 200084, 'box-sizing', 'box-sizing, border-box, content-box', 2, TRUE, 3),
  (148, 200084, 'Effect on element size', 'width, height, total size, calculate', 1, FALSE, 4);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200084, 3);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200085, 'TECHNICAL_INTERVIEW', 'EASY', 'TEXT', 'HTML', 'What is semantic HTML and why does it matter?', NULL, 'Semantic elements such as header, nav, main, article and footer describe the role of content instead of just styling it. They help screen readers and keyboard users, improve search engine understanding and make the code easier to maintain than a page built from generic div elements.', TRUE);
INSERT INTO interview_rubric_concepts (id, question_id, name, keywords, weight, required, display_order) VALUES
  (149, 200085, 'Elements describe meaning', 'semantic, meaning, describe, purpose', 2, TRUE, 1),
  (150, 200085, 'Examples of semantic elements', 'header, nav, main, article, section, footer', 2, TRUE, 2),
  (151, 200085, 'Accessibility benefits', 'accessib, screen reader, assistive', 2, TRUE, 3),
  (152, 200085, 'SEO and maintainability', 'seo, search engine, maintain, readab', 1, FALSE, 4);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200085, 3);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200086, 'TECHNICAL_INTERVIEW', 'EASY', 'TEXT', 'JavaScript', 'What is the difference between var, let and const?', NULL, 'var is function scoped and hoisted, so it can be used before its declaration and leaks out of blocks. let and const are block scoped and cannot be accessed before declaration (temporal dead zone). const prevents reassignment of the binding, although an object stored in it can still be changed. Prefer const by default and let when you must reassign.', TRUE);
INSERT INTO interview_rubric_concepts (id, question_id, name, keywords, weight, required, display_order) VALUES
  (153, 200086, 'var is function scoped', 'var, function scope, function-scoped, hoist', 2, TRUE, 1),
  (154, 200086, 'let and const are block scoped', 'let, const, block scope, block-scoped', 2, TRUE, 2),
  (155, 200086, 'const cannot be reassigned', 'const, reassign, constant, cannot change', 2, TRUE, 3),
  (156, 200086, 'Temporal dead zone', 'temporal dead zone, tdz, before declaration', 1, FALSE, 4);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200086, 3);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200087, 'TECHNICAL_INTERVIEW', 'EASY', 'TEXT', 'Responsive Design', 'What is responsive design and how do you implement it?', NULL, 'Responsive design makes one codebase work well on phones, tablets and desktops. Add the viewport meta tag, use flexible layouts such as flexbox and grid with relative units, and apply media queries at breakpoints. A mobile-first approach starts with the smallest screen and adds rules for larger ones.', TRUE);
INSERT INTO interview_rubric_concepts (id, question_id, name, keywords, weight, required, display_order) VALUES
  (157, 200087, 'Layout adapts to screen size', 'adapt, screen size, different devices, mobile, viewport', 2, TRUE, 1),
  (158, 200087, 'Media queries', 'media quer, @media, breakpoint', 2, TRUE, 2),
  (159, 200087, 'Flexible units and layouts', 'flexbox, grid, percentage, rem, relative unit, fluid', 2, TRUE, 3),
  (160, 200087, 'Viewport meta tag and mobile-first', 'viewport, meta, mobile-first, mobile first', 1, FALSE, 4);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200087, 3);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200088, 'TECHNICAL_INTERVIEW', 'EASY', 'TEXT', 'Web Basics', 'What happens when you type a URL into the browser and press Enter?', NULL, 'The browser resolves the domain to an IP address through DNS, opens a connection (TCP and TLS for HTTPS) and sends an HTTP request. The server responds with HTML, and the browser parses it into the DOM, fetches CSS and JavaScript, builds the render tree, lays out the page and paints it.', TRUE);
INSERT INTO interview_rubric_concepts (id, question_id, name, keywords, weight, required, display_order) VALUES
  (161, 200088, 'DNS lookup', 'dns, domain name, ip address', 2, TRUE, 1),
  (162, 200088, 'HTTP request to the server', 'http, request, server, get request, tcp, tls, https', 2, TRUE, 2),
  (163, 200088, 'Server returns HTML, CSS and JavaScript', 'response, html, css, javascript', 1, TRUE, 3),
  (164, 200088, 'Browser parses and renders', 'pars, dom, render, paint, layout', 2, TRUE, 4);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200088, 3);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200089, 'TECHNICAL_INTERVIEW', 'MEDIUM', 'TEXT', 'JavaScript', 'What is event bubbling and how does event delegation use it?', NULL, 'When an event fires on an element it bubbles up through its ancestors. With event delegation you attach one listener to a common parent and use event.target to see which child triggered it. This uses less memory and also works for elements added later, such as items in a dynamic list.', TRUE);
INSERT INTO interview_rubric_concepts (id, question_id, name, keywords, weight, required, display_order) VALUES
  (165, 200089, 'Events travel up from the target to ancestors', 'bubbl, propagate, ancestor, parent, up the dom', 2, TRUE, 1),
  (166, 200089, 'Delegation attaches one listener to a parent', 'delegat, parent, single listener, one listener', 2, TRUE, 2),
  (167, 200089, 'event.target identifies the source', 'event.target, target, currenttarget', 1, TRUE, 3),
  (168, 200089, 'Benefits for dynamic lists', 'dynamic, performance, memory, many elements', 1, FALSE, 4);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200089, 3);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200090, 'TECHNICAL_INTERVIEW', 'MEDIUM', 'TEXT', 'JavaScript', 'What is a closure in JavaScript? Give a practical use.', NULL, 'A closure is a function together with the variables of the scope where it was created. It keeps access to those variables even after the outer function has finished. Typical uses are private state such as a counter, callbacks and event handlers, memoisation and the module pattern.', TRUE);
INSERT INTO interview_rubric_concepts (id, question_id, name, keywords, weight, required, display_order) VALUES
  (169, 200090, 'Function remembers its outer scope', 'remember, outer scope, lexical, enclos, outer function', 3, TRUE, 1),
  (170, 200090, 'Works after the outer function returned', 'after, returned, still access, persist', 2, TRUE, 2),
  (171, 200090, 'Practical use', 'counter, private, data hiding, callback, memoiz, module', 2, TRUE, 3);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200090, 3);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200091, 'TECHNICAL_INTERVIEW', 'MEDIUM', 'TEXT', 'React', 'What is the difference between props and state in React?', NULL, 'Props are values passed down from a parent and must not be modified by the child. State is data owned and updated by the component itself, usually with useState. Updating state schedules a re-render, while data that changes over time but is needed by children is passed down as props.', TRUE);
INSERT INTO interview_rubric_concepts (id, question_id, name, keywords, weight, required, display_order) VALUES
  (172, 200091, 'Props are inputs from a parent', 'props, parent, passed, input', 2, TRUE, 1),
  (173, 200091, 'State is owned by the component', 'state, usestate, internal, local, owned', 2, TRUE, 2),
  (174, 200091, 'Props are read only', 'read-only, read only, immutable, cannot modify, not be modified, must not be modified, should not modify', 2, TRUE, 3),
  (175, 200091, 'Changing state re-renders', 're-render, rerender, setstate, update', 1, FALSE, 4);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200091, 3);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200092, 'TECHNICAL_INTERVIEW', 'MEDIUM', 'TEXT', 'JavaScript', 'Explain Promises and async/await. How do they handle errors?', NULL, 'A Promise represents the eventual result of an asynchronous operation and is pending, fulfilled or rejected. async functions return promises and await pauses the function until the promise settles, so asynchronous code reads like synchronous code. Handle errors with .catch() or try/catch around await. Promise.all runs several promises concurrently.', TRUE);
INSERT INTO interview_rubric_concepts (id, question_id, name, keywords, weight, required, display_order) VALUES
  (176, 200092, 'A Promise represents a future value', 'promise, future, eventual, pending, resolved', 2, TRUE, 1),
  (177, 200092, 'async/await is syntax over promises', 'async, await, syntactic, sequential, readab', 2, TRUE, 2),
  (178, 200092, 'Errors with catch or try/catch', 'catch, try, reject, error handling', 2, TRUE, 3),
  (179, 200092, 'Parallel work with Promise.all', 'promise.all, parallel, concurrent', 1, FALSE, 4);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200092, 3);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200093, 'TECHNICAL_INTERVIEW', 'MEDIUM', 'TEXT', 'CSS Layout', 'When would you use Flexbox and when would you use CSS Grid?', NULL, 'Flexbox lays out items along one axis, which suits navigation bars, toolbars and centring content. CSS Grid controls rows and columns at the same time, which suits page layouts and card galleries. They work well together, for example a grid for the page and flexbox inside each card.', TRUE);
INSERT INTO interview_rubric_concepts (id, question_id, name, keywords, weight, required, display_order) VALUES
  (180, 200093, 'Flexbox is one-dimensional', 'one-dimensional, one dimensional, row or column, single axis, one axis, along one', 2, TRUE, 1),
  (181, 200093, 'Grid is two-dimensional', 'two-dimensional, two dimensional, rows and columns, grid', 2, TRUE, 2),
  (182, 200093, 'Typical use cases', 'navbar, toolbar, card, page layout, align, center', 2, TRUE, 3),
  (183, 200093, 'They can be combined', 'combine, together, nested', 1, FALSE, 4);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200093, 3);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200094, 'TECHNICAL_INTERVIEW', 'HARD', 'TEXT', 'React Performance', 'How does React re-render components, and how would you optimise a slow React app?', NULL, 'React compares the new virtual DOM with the previous one (reconciliation) and updates only what changed. To optimise, first measure with the React Profiler. Then avoid unnecessary renders with React.memo, useMemo and useCallback, use stable keys, virtualise long lists and split code with lazy loading.', TRUE);
INSERT INTO interview_rubric_concepts (id, question_id, name, keywords, weight, required, display_order) VALUES
  (184, 200094, 'Virtual DOM and reconciliation', 'virtual dom, reconcil, diff', 2, TRUE, 1),
  (185, 200094, 'Avoid unnecessary re-renders', 'react.memo, memo, usememo, usecallback, unnecessary', 2, TRUE, 2),
  (186, 200094, 'Stable keys in lists', 'key, keys, list', 1, TRUE, 3),
  (187, 200094, 'Measure and split code', 'profiler, measure, lazy, code splitting, virtuali', 2, TRUE, 4);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200094, 3);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200095, 'TECHNICAL_INTERVIEW', 'HARD', 'TEXT', 'JavaScript', 'Explain the JavaScript event loop, including microtasks and macrotasks.', NULL, 'JavaScript runs on one thread with a call stack. Asynchronous work is handled by the browser and its callbacks are placed in queues. After each task the event loop runs all microtasks (promise callbacks) before the next macrotask such as a setTimeout callback. Long synchronous code blocks the loop and freezes the UI.', TRUE);
INSERT INTO interview_rubric_concepts (id, question_id, name, keywords, weight, required, display_order) VALUES
  (188, 200095, 'Single-threaded with a call stack', 'single thread, single-thread, call stack', 2, TRUE, 1),
  (189, 200095, 'Task queues', 'queue, callback, web api, task', 2, TRUE, 2),
  (190, 200095, 'Microtasks run before macrotasks', 'microtask, promise, macrotask, settimeout', 3, TRUE, 3),
  (191, 200095, 'Why it matters', 'block, non-blocking, ui, freeze', 1, FALSE, 4);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200095, 3);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200096, 'TECHNICAL_INTERVIEW', 'HARD', 'TEXT', 'Performance', 'How would you improve the loading performance of a web page?', NULL, 'Start by measuring with Lighthouse and the Core Web Vitals (LCP, CLS, INP). Then reduce JavaScript with minification, tree shaking and code splitting, compress and lazy load images, use caching and a CDN, and avoid render-blocking resources with defer and critical CSS.', TRUE);
INSERT INTO interview_rubric_concepts (id, question_id, name, keywords, weight, required, display_order) VALUES
  (192, 200096, 'Measure with Lighthouse and Core Web Vitals', 'lighthouse, core web vitals, lcp, cls, inp, measure', 2, TRUE, 1),
  (193, 200096, 'Reduce and split JavaScript', 'bundle, code splitting, minif, tree shaking, lazy', 2, TRUE, 2),
  (194, 200096, 'Optimise images and use caching or a CDN', 'image, webp, lazy load, cache, cdn, compress', 2, TRUE, 3),
  (195, 200096, 'Avoid render-blocking resources', 'render-blocking, defer, async, critical css, preload', 1, FALSE, 4);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200096, 3);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200097, 'TECHNICAL_INTERVIEW', 'HARD', 'TEXT', 'Accessibility', 'How do you make a web application accessible?', NULL, 'Use semantic HTML and real form labels, make everything usable with a keyboard with a logical focus order, add alt text and ARIA attributes only where native elements are not enough, keep sufficient colour contrast (WCAG) and test with tools such as axe and a screen reader.', TRUE);
INSERT INTO interview_rubric_concepts (id, question_id, name, keywords, weight, required, display_order) VALUES
  (196, 200097, 'Semantic HTML', 'semantic, native element, button, label', 2, TRUE, 1),
  (197, 200097, 'Keyboard navigation and focus', 'keyboard, focus, tab order, tabindex', 2, TRUE, 2),
  (198, 200097, 'ARIA and text alternatives', 'aria, alt text, alt, screen reader', 2, TRUE, 3),
  (199, 200097, 'Colour contrast and testing', 'contrast, wcag, axe, test', 1, FALSE, 4);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200097, 3);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200098, 'TECHNICAL_INTERVIEW', 'HARD', 'TEXT', 'Security', 'What is XSS and how do you prevent it in a front-end application? How is it different from CORS?', NULL, 'In XSS an attacker gets the page to run malicious script. Prevent it by escaping or sanitising untrusted data, avoiding innerHTML and dangerouslySetInnerHTML, and using a Content Security Policy. CORS is a different mechanism: it controls which origins may read responses from a server and does not stop injected scripts.', TRUE);
INSERT INTO interview_rubric_concepts (id, question_id, name, keywords, weight, required, display_order) VALUES
  (200, 200098, 'XSS injects malicious scripts', 'xss, cross-site scripting, inject, script', 2, TRUE, 1),
  (201, 200098, 'Escape and sanitise output', 'escap, sanitiz, sanitis, dangerouslysetinnerhtml, innerhtml', 2, TRUE, 2),
  (202, 200098, 'Content Security Policy', 'csp, content security policy', 1, TRUE, 3),
  (203, 200098, 'CORS controls cross-origin access', 'cors, cross-origin, origin, same-origin', 2, TRUE, 4);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200098, 3);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200099, 'TECHNICAL_INTERVIEW', 'EASY', 'TEXT', 'Web Architecture', 'Explain the client-server model and the request-response cycle in a web application.', NULL, 'The browser (client) sends an HTTP request, for example GET or POST, to the server. The backend processes it, may read or write a database, and returns a response with a status code and data such as HTML or JSON. The client then renders the response.', TRUE);
INSERT INTO interview_rubric_concepts (id, question_id, name, keywords, weight, required, display_order) VALUES
  (204, 200099, 'Client sends requests', 'client, browser, request', 2, TRUE, 1),
  (205, 200099, 'Server processes and responds', 'server, response, backend, process', 2, TRUE, 2),
  (206, 200099, 'HTTP methods and status codes', 'http, get, post, status code, 200, 404', 2, TRUE, 3),
  (207, 200099, 'Data stored in a database', 'database, sql, persist, store', 1, FALSE, 4);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200099, 4);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200100, 'TECHNICAL_INTERVIEW', 'EASY', 'TEXT', 'APIs', 'What is a REST API? Which HTTP methods and status codes do you use?', NULL, 'A REST API exposes resources through URLs and uses HTTP methods: GET to read, POST to create, PUT or PATCH to update and DELETE to remove. It is stateless, so each request carries everything needed. Status codes tell the result: 200 OK, 201 Created, 400 Bad Request, 401 Unauthorized, 404 Not Found and 500 for server errors.', TRUE);
INSERT INTO interview_rubric_concepts (id, question_id, name, keywords, weight, required, display_order) VALUES
  (208, 200100, 'Resources identified by URLs', 'resource, url, endpoint, noun', 2, TRUE, 1),
  (209, 200100, 'HTTP methods for actions', 'get, post, put, delete, patch', 2, TRUE, 2),
  (210, 200100, 'Stateless communication', 'stateless, no session, each request', 1, TRUE, 3),
  (211, 200100, 'Status codes', '200, 201, 400, 401, 404, 500, status code', 2, TRUE, 4);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200100, 4);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200101, 'TECHNICAL_INTERVIEW', 'EASY', 'TEXT', 'Databases', 'What are primary keys and foreign keys, and why are they important?', NULL, 'A primary key uniquely identifies each row. A foreign key is a column that references the primary key of another table and links related data, such as orders.customer_id referring to customers.id. Together they enforce referential integrity, so you cannot create an order for a customer that does not exist.', TRUE);
INSERT INTO interview_rubric_concepts (id, question_id, name, keywords, weight, required, display_order) VALUES
  (212, 200101, 'Primary key identifies a row uniquely', 'primary key, unique, identif', 2, TRUE, 1),
  (213, 200101, 'Foreign key references another table', 'foreign key, reference, another table, parent table', 2, TRUE, 2),
  (214, 200101, 'Referential integrity', 'integrity, consistent, orphan, constraint', 2, TRUE, 3),
  (215, 200101, 'Example', 'for example, orders, customer, user_id', 1, FALSE, 4);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200101, 4);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200102, 'TECHNICAL_INTERVIEW', 'EASY', 'TEXT', 'Data Exchange', 'How do the front end and back end exchange data, and what is JSON?', NULL, 'The front end sends HTTP requests with fetch or axios and the back end replies with JSON, a lightweight text format of key-value pairs and arrays. The server serialises objects to JSON and the client parses it back into objects. The Content-Type: application/json header describes the body.', TRUE);
INSERT INTO interview_rubric_concepts (id, question_id, name, keywords, weight, required, display_order) VALUES
  (216, 200102, 'JSON is a text format for data', 'json, text format, key-value, lightweight', 2, TRUE, 1),
  (217, 200102, 'Front end calls the API', 'fetch, axios, ajax, http request, api call', 2, TRUE, 2),
  (218, 200102, 'Serialisation and parsing', 'serializ, serialis, parse, stringify, convert', 1, TRUE, 3),
  (219, 200102, 'Content-Type header', 'content-type, application/json, header', 1, FALSE, 4);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200102, 4);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200103, 'TECHNICAL_INTERVIEW', 'EASY', 'TEXT', 'Architecture', 'What is the MVC pattern and how does it relate to a full stack application?', NULL, 'In MVC the Model holds data and business rules, the View renders the user interface and the Controller receives requests and coordinates them. Separating these responsibilities makes the code easier to maintain and test. In a typical full stack app, entities and services are the model, controllers expose the API and React is the view.', TRUE);
INSERT INTO interview_rubric_concepts (id, question_id, name, keywords, weight, required, display_order) VALUES
  (220, 200103, 'Model holds data and business rules', 'model, data, business logic, entity', 2, TRUE, 1),
  (221, 200103, 'View shows the user interface', 'view, ui, template, presentation, react', 2, TRUE, 2),
  (222, 200103, 'Controller handles requests', 'controller, request, route, handler', 2, TRUE, 3),
  (223, 200103, 'Separation of concerns', 'separation of concerns, maintain, test, responsibilit', 1, FALSE, 4);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200103, 4);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200104, 'TECHNICAL_INTERVIEW', 'MEDIUM', 'TEXT', 'Authentication', 'Explain how JWT-based authentication works from login to a protected request.', NULL, 'After a successful login the server returns a signed JWT. The client stores it and sends it in the Authorization: Bearer header on each request. The server verifies the signature and expiry and extracts the user identity. Use HTTPS, short expiry times and hashed passwords.', TRUE);
INSERT INTO interview_rubric_concepts (id, question_id, name, keywords, weight, required, display_order) VALUES
  (224, 200104, 'Login with credentials', 'login, credentials, username, password', 1, TRUE, 1),
  (225, 200104, 'Server issues a signed token', 'sign, token, issue, secret, generate', 2, TRUE, 2),
  (226, 200104, 'Client sends the token with each request', 'authorization, bearer, header, each request', 2, TRUE, 3),
  (227, 200104, 'Server verifies signature and expiry', 'verif, validate, expir, signature', 2, TRUE, 4),
  (228, 200104, 'Security measures', 'https, short-lived, refresh, hash, bcrypt', 1, FALSE, 5);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200104, 4);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200105, 'TECHNICAL_INTERVIEW', 'MEDIUM', 'TEXT', 'Browser Security', 'What is CORS and how do you fix a CORS error between a React app and a Spring Boot API?', NULL, 'Browsers block responses from a different origin (scheme, host or port) unless the server permits it with CORS headers. Configure the backend, for example CorsConfiguration in Spring Security with the frontend origin allowed, including methods and headers for the preflight OPTIONS request. In development a dev-server proxy is another option.', TRUE);
INSERT INTO interview_rubric_concepts (id, question_id, name, keywords, weight, required, display_order) VALUES
  (229, 200105, 'Browsers restrict cross-origin requests', 'same-origin, cross-origin, origin, browser blocks', 2, TRUE, 1),
  (230, 200105, 'Server must allow the origin', 'access-control-allow-origin, allowed origin, allow the origin, origin allowed, cors configuration, cors headers, permits', 2, TRUE, 2),
  (231, 200105, 'Preflight requests', 'preflight, options', 1, TRUE, 3),
  (232, 200105, 'Configure the backend', 'corsconfiguration, @crossorigin, allowedorigins, spring, proxy', 2, TRUE, 4);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200105, 4);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200106, 'TECHNICAL_INTERVIEW', 'MEDIUM', 'TEXT', 'Database Design', 'How would you design the database for an online store''s orders? Mention normalisation.', NULL, 'Use customers, products, orders and order_items tables. An order belongs to a customer (one-to-many) and order_items link orders to products with quantity and the price at purchase. Use primary and foreign keys and normalise the data to avoid redundancy, while storing a snapshot of the price so history stays correct.', TRUE);
INSERT INTO interview_rubric_concepts (id, question_id, name, keywords, weight, required, display_order) VALUES
  (233, 200106, 'Separate tables for customers, orders and products', 'customer, order, product, table', 2, TRUE, 1),
  (234, 200106, 'Order items link orders and products', 'order_item, order item, join table, many-to-many, line item', 2, TRUE, 2),
  (235, 200106, 'Keys and relationships', 'primary key, foreign key, one-to-many, relationship', 2, TRUE, 3),
  (236, 200106, 'Normalisation and price history', 'normali, redundan, price at purchase, snapshot', 1, FALSE, 4);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200106, 4);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200107, 'TECHNICAL_INTERVIEW', 'MEDIUM', 'TEXT', 'Front-end Architecture', 'How do you manage state in a large React application, and when would you use Context or a library like Redux?', NULL, 'Keep state local when possible. Use Context for values shared widely and rarely changing, such as the current user or theme. For complex, frequently updated global state use a store such as Redux or Zustand. For data from the server a data-fetching library such as React Query manages caching and loading states.', TRUE);
INSERT INTO interview_rubric_concepts (id, question_id, name, keywords, weight, required, display_order) VALUES
  (237, 200107, 'Local state first', 'local state, state local, keep state, usestate, component state', 2, TRUE, 1),
  (238, 200107, 'Context for shared values', 'context, usecontext, provider, theme, auth', 2, TRUE, 2),
  (239, 200107, 'Redux or similar for complex state', 'redux, zustand, store, reducer, global state', 2, TRUE, 3),
  (240, 200107, 'Server state with a data-fetching library', 'react query, swr, cache, server state', 1, FALSE, 4);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200107, 4);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200108, 'TECHNICAL_INTERVIEW', 'MEDIUM', 'TEXT', 'Error Handling', 'How do you handle validation and errors consistently across the front end and back end?', NULL, 'Validate in the browser for fast feedback and always again on the server, because client checks can be bypassed. The API should return consistent error responses with proper status codes, handled centrally, for example with @ControllerAdvice in Spring. The UI then shows clear field and general messages.', TRUE);
INSERT INTO interview_rubric_concepts (id, question_id, name, keywords, weight, required, display_order) VALUES
  (241, 200108, 'Validate on both sides', 'both, client-side, server-side, in the browser, on the server, front end and back end, never trust', 2, TRUE, 1),
  (242, 200108, 'Meaningful status codes and messages', 'status code, 400, 422, error message, consistent', 2, TRUE, 2),
  (243, 200108, 'Global exception handling', 'exception handler, controlleradvice, global, centralized', 2, TRUE, 3),
  (244, 200108, 'Show errors to the user', 'display, toast, field error, user-friendly, shows clear, the ui, messages', 1, FALSE, 4);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200108, 4);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200109, 'TECHNICAL_INTERVIEW', 'HARD', 'TEXT', 'Scalability', 'How would you design a web application so it can handle ten times more users?', NULL, 'Make the application servers stateless and scale them horizontally behind a load balancer. Add caching with a CDN and an in-memory cache such as Redis. Scale the database with indexes, read replicas and connection pooling, move slow work to queues and use monitoring to find the next bottleneck.', TRUE);
INSERT INTO interview_rubric_concepts (id, question_id, name, keywords, weight, required, display_order) VALUES
  (245, 200109, 'Stateless servers behind a load balancer', 'load balancer, stateless, horizontal, scale out', 2, TRUE, 1),
  (246, 200109, 'Caching', 'cache, redis, cdn', 2, TRUE, 2),
  (247, 200109, 'Database scaling', 'index, replica, read replica, shard, partition, connection pool', 2, TRUE, 3),
  (248, 200109, 'Asynchronous work and monitoring', 'queue, async, message, kafka, monitor, metric', 1, FALSE, 4);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200109, 4);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200110, 'TECHNICAL_INTERVIEW', 'HARD', 'TEXT', 'Performance', 'How do you find and fix slow database queries in a web application?', NULL, 'Find slow queries with the slow query log or an APM tool and inspect them with EXPLAIN. Add indexes for columns used in WHERE, JOIN and ORDER BY, fix N+1 queries with join fetch or batching, paginate and select only needed columns, and cache results that rarely change.', TRUE);
INSERT INTO interview_rubric_concepts (id, question_id, name, keywords, weight, required, display_order) VALUES
  (249, 200110, 'Measure with logs, EXPLAIN or APM', 'explain, slow query, profil, log, apm', 2, TRUE, 1),
  (250, 200110, 'Add the right indexes', 'index', 2, TRUE, 2),
  (251, 200110, 'Fix the N+1 problem and fetch less data', 'n+1, join fetch, pagination, select only, limit', 2, TRUE, 3),
  (252, 200110, 'Caching', 'cache, redis', 1, FALSE, 4);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200110, 4);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200111, 'TECHNICAL_INTERVIEW', 'HARD', 'TEXT', 'Security', 'Name common web application vulnerabilities and how you would protect against them.', NULL, 'Use parameterised queries to prevent SQL injection, escape output and add a Content Security Policy against XSS, use CSRF tokens or SameSite cookies for cookie-based sessions, hash passwords with bcrypt, enforce authorisation on every endpoint, use HTTPS and apply least privilege.', TRUE);
INSERT INTO interview_rubric_concepts (id, question_id, name, keywords, weight, required, display_order) VALUES
  (253, 200111, 'SQL injection prevented by parameterised queries', 'sql injection, prepared statement, parameteri', 2, TRUE, 1),
  (254, 200111, 'XSS prevented by escaping and CSP', 'xss, escap, sanitiz, content security policy', 2, TRUE, 2),
  (255, 200111, 'CSRF protection', 'csrf, token, samesite', 1, TRUE, 3),
  (256, 200111, 'Authentication, hashing and HTTPS', 'bcrypt, hash, https, authorization, least privilege', 2, TRUE, 4);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200111, 4);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200112, 'TECHNICAL_INTERVIEW', 'HARD', 'TEXT', 'DevOps', 'Describe a CI/CD pipeline you would set up for a full stack application.', NULL, 'On every push the pipeline builds the front end and back end, runs linting and unit and integration tests, and then builds a Docker image. A successful main branch deploys to staging and then to production with approval or automatically. Keep environment configuration outside the code and have a rollback strategy.', TRUE);
INSERT INTO interview_rubric_concepts (id, question_id, name, keywords, weight, required, display_order) VALUES
  (257, 200112, 'Build and test on every commit', 'build, test, commit, push, pull request', 2, TRUE, 1),
  (258, 200112, 'Automated checks', 'lint, unit test, integration test, quality', 1, TRUE, 2),
  (259, 200112, 'Automated deployment', 'deploy, release, staging, production', 2, TRUE, 3),
  (260, 200112, 'Containers and rollback', 'docker, container, rollback, blue-green, environment', 1, FALSE, 4);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200112, 4);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200113, 'TECHNICAL_INTERVIEW', 'HARD', 'TEXT', 'Reliability', 'How would you make a payment endpoint safe against duplicate requests and partial failures?', NULL, 'Require a client-generated idempotency key and store the result so a retried request returns the same outcome instead of charging twice. Wrap related changes in a database transaction so they succeed or fail together, handle timeouts and retries explicitly, and keep an audit trail and reconciliation with the payment provider.', TRUE);
INSERT INTO interview_rubric_concepts (id, question_id, name, keywords, weight, required, display_order) VALUES
  (261, 200113, 'Idempotency keys', 'idempotenc, idempotent, request id, unique key', 3, TRUE, 1),
  (262, 200113, 'Database transactions', 'transaction, atomic, commit, rollback', 2, TRUE, 2),
  (263, 200113, 'Handle retries and timeouts', 'retry, timeout, duplicate, exactly once', 1, TRUE, 3),
  (264, 200113, 'Audit and reconciliation', 'audit, log, reconcil, webhook', 1, FALSE, 4);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200113, 4);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200114, 'TECHNICAL_INTERVIEW', 'EASY', 'TEXT', 'Java Platform', 'Explain the difference between the JDK, the JRE and the JVM.', NULL, 'The JVM runs compiled bytecode and makes Java platform independent. The JRE bundles the JVM with the standard libraries needed to run programs. The JDK contains the JRE plus development tools such as the javac compiler, so you need the JDK to write Java and only the JRE to run it.', TRUE);
INSERT INTO interview_rubric_concepts (id, question_id, name, keywords, weight, required, display_order) VALUES
  (265, 200114, 'JVM executes bytecode', 'jvm, bytecode, virtual machine', 2, TRUE, 1),
  (266, 200114, 'JRE supplies the runtime libraries', 'jre, runtime environment, class librar, libraries', 1, TRUE, 2),
  (267, 200114, 'JDK adds development tools', 'jdk, compiler, javac, development kit, tools', 2, TRUE, 3),
  (268, 200114, 'Platform independence', 'platform independen, write once, portable, any os', 1, FALSE, 4);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200114, 1);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200115, 'TECHNICAL_INTERVIEW', 'EASY', 'TEXT', 'OOP', 'What are the four pillars of object-oriented programming? Give a short example of each.', NULL, 'Encapsulation bundles data with methods and hides fields behind getters and setters. Inheritance lets a class reuse another class using extends. Polymorphism lets one interface have many forms through overriding and overloading. Abstraction exposes what an object does and hides how, using abstract classes and interfaces.', TRUE);
INSERT INTO interview_rubric_concepts (id, question_id, name, keywords, weight, required, display_order) VALUES
  (269, 200115, 'Encapsulation', 'encapsulat, private field, getter, setter, data hiding', 2, TRUE, 1),
  (270, 200115, 'Inheritance', 'inherit, extends, subclass, parent class', 2, TRUE, 2),
  (271, 200115, 'Polymorphism', 'polymorph, overrid, overload, many forms', 2, TRUE, 3),
  (272, 200115, 'Abstraction', 'abstract, interface, hide complexity, hides implementation', 2, TRUE, 4),
  (273, 200115, 'Gives an example', 'for example, e.g., such as, class animal, class dog', 1, FALSE, 5);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200115, 1);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200116, 'TECHNICAL_INTERVIEW', 'EASY', 'TEXT', 'Equality', 'What is the difference between == and equals() in Java?', NULL, 'For objects, == checks whether two references point to the same object, while equals() checks logical equality and is meant to be overridden. Two Strings with the same text created with new are not == but are equals. When equals() is overridden, hashCode() must be overridden consistently.', TRUE);
INSERT INTO interview_rubric_concepts (id, question_id, name, keywords, weight, required, display_order) VALUES
  (274, 200116, '== compares references for objects', 'reference, same object, memory address, identity', 2, TRUE, 1),
  (275, 200116, 'equals compares logical content', 'equals, content, value, overrid', 2, TRUE, 2),
  (276, 200116, 'String pool example', 'string pool, literal, new string', 1, FALSE, 3),
  (277, 200116, 'hashCode contract', 'hashcode, hash code, contract, hashmap', 1, FALSE, 4);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200116, 1);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200117, 'TECHNICAL_INTERVIEW', 'EASY', 'TEXT', 'Collections', 'How do ArrayList and LinkedList differ, and when would you use each?', NULL, 'ArrayList stores elements in an array, giving O(1) access by index but costly insertions in the middle because elements shift. LinkedList stores nodes with links, so insertion at a known node is cheap but access by index is O(n). ArrayList is the default choice for most cases.', TRUE);
INSERT INTO interview_rubric_concepts (id, question_id, name, keywords, weight, required, display_order) VALUES
  (278, 200117, 'ArrayList uses a resizable array', 'array, resiz, dynamic array, contiguous', 2, TRUE, 1),
  (279, 200117, 'ArrayList has fast random access', 'random access, get(i), index, o(1)', 1, TRUE, 2),
  (280, 200117, 'LinkedList uses nodes', 'node, doubly linked, pointer, linked', 2, TRUE, 3),
  (281, 200117, 'Insertion and deletion cost', 'insert, delet, middle, o(n), shift', 1, FALSE, 4);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200117, 1);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200118, 'TECHNICAL_INTERVIEW', 'EASY', 'TEXT', 'Exceptions', 'Explain checked and unchecked exceptions in Java with examples.', NULL, 'Checked exceptions such as IOException must be caught or declared with throws, and the compiler enforces this. Unchecked exceptions such as NullPointerException extend RuntimeException and need not be declared. Use checked exceptions for recoverable conditions and unchecked ones for programming errors.', TRUE);
INSERT INTO interview_rubric_concepts (id, question_id, name, keywords, weight, required, display_order) VALUES
  (282, 200118, 'Checked exceptions are verified at compile time', 'checked, compile time, compile-time, must handle', 2, TRUE, 1),
  (283, 200118, 'Handle or declare', 'try, catch, throws, declare', 1, TRUE, 2),
  (284, 200118, 'Unchecked exceptions extend RuntimeException', 'unchecked, runtimeexception, runtime exception', 2, TRUE, 3),
  (285, 200118, 'Examples', 'ioexception, sqlexception, nullpointer, arithmetic, illegalargument', 1, FALSE, 4);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200118, 1);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200119, 'TECHNICAL_INTERVIEW', 'MEDIUM', 'TEXT', 'Collections Internals', 'How does a HashMap work internally?', NULL, 'HashMap computes the key''s hash to choose a bucket. Keys that land in the same bucket form a linked list, which becomes a balanced tree when it grows long. equals() identifies the exact key. When the number of entries passes the load factor (0.75) the table is resized and entries are rehashed.', TRUE);
INSERT INTO interview_rubric_concepts (id, question_id, name, keywords, weight, required, display_order) VALUES
  (286, 200119, 'Hash code selects a bucket', 'hashcode, hash code, bucket, hash function, index', 2, TRUE, 1),
  (287, 200119, 'Collisions are handled in the bucket', 'collision, linked list, tree, treeif, chain', 2, TRUE, 2),
  (288, 200119, 'equals finds the matching key', 'equals, same key, key match', 1, TRUE, 3),
  (289, 200119, 'Resize at the load factor', 'load factor, 0.75, resiz, rehash, capacity', 1, FALSE, 4);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200119, 1);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200120, 'TECHNICAL_INTERVIEW', 'MEDIUM', 'TEXT', 'OOP', 'Explain method overloading and method overriding.', NULL, 'Overloading means several methods with the same name but different parameter lists in one class, resolved at compile time. Overriding means a subclass provides its own implementation of an inherited method with the same signature, resolved at runtime by the actual object type. Static, private and final methods cannot be overridden.', TRUE);
INSERT INTO interview_rubric_concepts (id, question_id, name, keywords, weight, required, display_order) VALUES
  (290, 200120, 'Overloading: same name, different parameters', 'overload, same name, different parameter, different signature', 2, TRUE, 1),
  (291, 200120, 'Overriding: subclass replaces a method', 'overrid, subclass, same signature, @override', 2, TRUE, 2),
  (292, 200120, 'Compile-time versus runtime binding', 'compile time, compile-time, runtime, dynamic dispatch, static binding', 2, TRUE, 3),
  (293, 200120, 'Static and private methods', 'static, private, final, hidden', 1, FALSE, 4);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200120, 1);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200121, 'TECHNICAL_INTERVIEW', 'MEDIUM', 'TEXT', 'OOP Design', 'When would you choose an abstract class over an interface?', NULL, 'Use an abstract class when related classes share state or common code. Use an interface to define a capability that unrelated classes can implement, because a class can implement many interfaces but extend only one class. Since Java 8 interfaces can have default methods, but they still cannot hold instance state.', TRUE);
INSERT INTO interview_rubric_concepts (id, question_id, name, keywords, weight, required, display_order) VALUES
  (294, 200121, 'Abstract class can hold state and constructors', 'state, field, constructor, instance variable', 2, TRUE, 1),
  (295, 200121, 'Interface defines a contract', 'contract, implements, capabilit, behaviou', 2, TRUE, 2),
  (296, 200121, 'Multiple inheritance of type', 'multiple, several interfaces, one class', 1, TRUE, 3),
  (297, 200121, 'Default methods and shared code', 'default method, shared code, common code, template', 1, FALSE, 4);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200121, 1);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200122, 'TECHNICAL_INTERVIEW', 'MEDIUM', 'TEXT', 'JVM', 'Explain the Java stack and heap and how garbage collection works.', NULL, 'Each thread has a stack with frames for method calls and local variables. Objects live on the shared heap. The garbage collector frees objects that are no longer reachable from GC roots. Most collectors use generations: new objects start in the young generation and survivors are promoted to the old generation.', TRUE);
INSERT INTO interview_rubric_concepts (id, question_id, name, keywords, weight, required, display_order) VALUES
  (298, 200122, 'Stack stores frames and local variables', 'stack, frame, local variable, primitive', 2, TRUE, 1),
  (299, 200122, 'Heap stores objects', 'heap, objects, new keyword, instances', 2, TRUE, 2),
  (300, 200122, 'GC reclaims unreachable objects', 'garbage collect, unreachable, reachab, gc root, reclaim', 2, TRUE, 3),
  (301, 200122, 'Generations', 'young, old generation, eden, minor gc, major gc', 1, FALSE, 4);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200122, 1);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200123, 'TECHNICAL_INTERVIEW', 'MEDIUM', 'TEXT', 'Spring', 'What is dependency injection and why is it useful in Spring?', NULL, 'With dependency injection an object receives the collaborators it needs from the Spring container instead of creating them. This is inversion of control. It gives loose coupling and makes classes easy to test, because dependencies can be replaced with mocks. Constructor injection is the recommended style.', TRUE);
INSERT INTO interview_rubric_concepts (id, question_id, name, keywords, weight, required, display_order) VALUES
  (302, 200123, 'The container creates and supplies dependencies', 'container, ioc, inversion of control, inject, bean', 2, TRUE, 1),
  (303, 200123, 'Constructor injection', 'constructor, @autowired, field injection, setter', 1, TRUE, 2),
  (304, 200123, 'Loose coupling', 'loose coupling, decoupl, interface, abstraction', 2, TRUE, 3),
  (305, 200123, 'Easier testing', 'test, mock, replace', 1, FALSE, 4);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200123, 1);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200124, 'TECHNICAL_INTERVIEW', 'HARD', 'TEXT', 'Immutability', 'How do you design an immutable class in Java, and why would you?', NULL, 'Declare the class final, make all fields private and final, provide no setters, and copy mutable inputs and outputs (defensive copies). Immutable objects are inherently thread safe, easy to reason about and safe as map keys. String and LocalDate are examples, and records make this easier.', TRUE);
INSERT INTO interview_rubric_concepts (id, question_id, name, keywords, weight, required, display_order) VALUES
  (306, 200124, 'final class and final fields', 'final class, final field, final', 2, TRUE, 1),
  (307, 200124, 'No setters', 'no setter, setter, cannot change, unmodifiable', 1, TRUE, 2),
  (308, 200124, 'Defensive copies of mutable fields', 'defensive cop, copy, mutable field, clone', 2, TRUE, 3),
  (309, 200124, 'Thread safety', 'thread safe, thread-safe, concurren, synchroniz', 2, TRUE, 4),
  (310, 200124, 'Example such as String', 'string, localdate, record', 1, FALSE, 5);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200124, 1);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200125, 'TECHNICAL_INTERVIEW', 'HARD', 'TEXT', 'Concurrency', 'Compare synchronized, volatile and atomic classes. When would you use each?', NULL, 'synchronized provides mutual exclusion and visibility for a block. volatile guarantees visibility and ordering of a single variable but not atomicity of compound actions. AtomicInteger and similar classes use compare-and-swap for lock-free atomic updates. Use volatile for simple flags, atomics for counters and synchronized or locks for multi-step invariants.', TRUE);
INSERT INTO interview_rubric_concepts (id, question_id, name, keywords, weight, required, display_order) VALUES
  (311, 200125, 'synchronized gives mutual exclusion', 'synchronized, mutual exclusion, lock, monitor', 2, TRUE, 1),
  (312, 200125, 'volatile gives visibility only', 'volatile, visibility, not atomic, happens-before', 2, TRUE, 2),
  (313, 200125, 'Atomic classes use compare-and-swap', 'atomic, compare-and-swap, cas, atomicinteger', 2, TRUE, 3),
  (314, 200125, 'Choosing by use case', 'counter, flag, compound, race condition', 1, FALSE, 4);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200125, 1);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200126, 'TECHNICAL_INTERVIEW', 'HARD', 'TEXT', 'Spring Transactions', 'How does @Transactional work in Spring and what are common pitfalls?', NULL, 'Spring wraps the bean in a proxy that opens a transaction before the method and commits or rolls back afterwards. By default it rolls back only for unchecked exceptions. A call from another method of the same class bypasses the proxy, so the annotation is ignored. Also understand propagation, isolation and readOnly settings.', TRUE);
INSERT INTO interview_rubric_concepts (id, question_id, name, keywords, weight, required, display_order) VALUES
  (315, 200126, 'Implemented with proxies and AOP', 'proxy, aop, aspect, intercept', 2, TRUE, 1),
  (316, 200126, 'Rollback on runtime exceptions by default', 'rollback, runtime exception, unchecked, checked exception', 2, TRUE, 2),
  (317, 200126, 'Self-invocation bypasses the proxy', 'self-invocation, self invocation, same class, bypass', 2, TRUE, 3),
  (318, 200126, 'Propagation and isolation', 'propagation, requires_new, isolation, readonly', 1, FALSE, 4);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200126, 1);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200127, 'TECHNICAL_INTERVIEW', 'HARD', 'TEXT', 'Troubleshooting', 'A Java service slowly runs out of memory. How would you diagnose and fix it?', NULL, 'Enable GC logging and take a heap dump when memory is high, then analyse it with a tool such as Eclipse MAT or VisualVM. Look for objects that stay reachable through static collections, caches without eviction, listeners or ThreadLocals. Fix the retention, for example with bounded caches or removing listeners, then monitor heap usage to confirm.', TRUE);
INSERT INTO interview_rubric_concepts (id, question_id, name, keywords, weight, required, display_order) VALUES
  (319, 200127, 'Capture a heap dump', 'heap dump, jmap, hprof, oom, outofmemory', 2, TRUE, 1),
  (320, 200127, 'Analyse with a profiler', 'visualvm, mat, memory analyzer, profiler, yourkit', 2, TRUE, 2),
  (321, 200127, 'Find what keeps objects reachable', 'gc root, static, cache, listener, threadlocal, leak', 2, TRUE, 3),
  (322, 200127, 'Fix and monitor', 'fix, monitor, gc log, metrics, limit, eviction', 1, FALSE, 4);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200127, 1);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200128, 'TECHNICAL_INTERVIEW', 'HARD', 'TEXT', 'System Design', 'How would you build a thread-safe in-memory cache in Java?', NULL, 'Use ConcurrentHashMap for thread-safe access, or a library such as Caffeine. Add an eviction policy such as LRU with a size limit, plus a time-to-live so stale entries expire. Consider cache stampedes, memory limits and how entries are invalidated when the source data changes.', TRUE);
INSERT INTO interview_rubric_concepts (id, question_id, name, keywords, weight, required, display_order) VALUES
  (323, 200128, 'Use a concurrent map', 'concurrenthashmap, concurrent map, thread-safe, thread safe', 2, TRUE, 1),
  (324, 200128, 'Eviction policy', 'eviction, lru, linkedhashmap, size limit, caffeine', 2, TRUE, 2),
  (325, 200128, 'Expiry or invalidation', 'ttl, expir, invalidat, stale', 1, TRUE, 3),
  (326, 200128, 'Memory and concurrency trade-offs', 'memory, trade-off, lock, contention, cache stampede', 1, FALSE, 4);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200128, 1);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200129, 'TECHNICAL_INTERVIEW', 'EASY', 'TEXT', 'Data Structures', 'Explain the difference between a list, tuple, set and dictionary in Python.', NULL, 'A list is an ordered mutable sequence. A tuple is an ordered immutable sequence, useful for fixed records and as dictionary keys. A set stores unique unordered items and gives fast membership tests. A dictionary maps keys to values and gives fast lookup by key.', TRUE);
INSERT INTO interview_rubric_concepts (id, question_id, name, keywords, weight, required, display_order) VALUES
  (327, 200129, 'List is ordered and mutable', 'list, ordered, mutable, append', 2, TRUE, 1),
  (328, 200129, 'Tuple is immutable', 'tuple, immutable, cannot change, fixed', 2, TRUE, 2),
  (329, 200129, 'Set holds unique items', 'set, unique, no duplicate, unordered', 2, TRUE, 3),
  (330, 200129, 'Dictionary stores key-value pairs', 'dict, key-value, key value, mapping, key', 2, TRUE, 4),
  (331, 200129, 'When to use each', 'for example, use when, lookup, membership', 1, FALSE, 5);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200129, 2);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200130, 'TECHNICAL_INTERVIEW', 'EASY', 'TEXT', 'Language Basics', 'What are mutable and immutable types in Python? Give examples and explain why it matters.', NULL, 'Lists, dictionaries and sets are mutable: they can be changed in place. Integers, strings and tuples are immutable. Because variables hold references, changing a mutable object through one name is visible through every other name, which can surprise you when passing lists to functions.', TRUE);
INSERT INTO interview_rubric_concepts (id, question_id, name, keywords, weight, required, display_order) VALUES
  (332, 200130, 'Mutable objects can change in place', 'mutable, change in place, modified in place, list, dict', 2, TRUE, 1),
  (333, 200130, 'Immutable objects cannot change', 'immutable, int, str, tuple, cannot be changed', 2, TRUE, 2),
  (334, 200130, 'Effect on function arguments and aliasing', 'reference, alias, same object, function argument, side effect', 2, TRUE, 3),
  (335, 200130, 'Hashability', 'hashable, dictionary key, hash', 1, FALSE, 4);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200130, 2);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200131, 'TECHNICAL_INTERVIEW', 'EASY', 'TEXT', 'Functions', 'What are *args and **kwargs and when do you use them?', NULL, '*args gathers any extra positional arguments into a tuple and **kwargs gathers extra keyword arguments into a dictionary. They are used for functions that accept a variable number of arguments, and for wrappers or decorators that pass arguments through.', TRUE);
INSERT INTO interview_rubric_concepts (id, question_id, name, keywords, weight, required, display_order) VALUES
  (336, 200131, '*args collects extra positional arguments', '*args, positional, tuple', 2, TRUE, 1),
  (337, 200131, '**kwargs collects keyword arguments', '**kwargs, keyword, dictionary, dict', 2, TRUE, 2),
  (338, 200131, 'Flexible function signatures', 'flexible, any number, variable number, wrapper, pass through', 1, TRUE, 3),
  (339, 200131, 'Unpacking when calling', 'unpack, *list, **dict', 1, FALSE, 4);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200131, 2);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200132, 'TECHNICAL_INTERVIEW', 'EASY', 'TEXT', 'Comprehensions', 'What is a list comprehension and how is it different from a normal for loop?', NULL, 'A list comprehension builds a list in one expression, for example [x * x for x in range(5) if x % 2 == 0]. It is usually shorter and slightly faster than appending in a loop. Use a normal loop when the logic is complex so the code stays readable.', TRUE);
INSERT INTO interview_rubric_concepts (id, question_id, name, keywords, weight, required, display_order) VALUES
  (340, 200132, 'Compact syntax for building a list', 'list comprehension, one line, concise, compact, build a list', 2, TRUE, 1),
  (341, 200132, 'Expression, loop and optional condition', 'for, in, if, condition, expression', 2, TRUE, 2),
  (342, 200132, 'Readability and performance', 'readab, faster, performance, clear', 1, TRUE, 3),
