INSERT INTO interview_question_roles (question_id, role_id) VALUES (200132, 2);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200133, 'TECHNICAL_INTERVIEW', 'EASY', 'TEXT', 'Errors', 'How does exception handling work in Python? Explain try, except, else and finally.', NULL, 'Put code that can fail in try. except catches specific exceptions. else runs only if no exception occurred, and finally always runs, so it is the right place for cleanup such as closing files. Catch specific exceptions instead of using a bare except.', TRUE);
INSERT INTO interview_rubric_concepts (id, question_id, name, keywords, weight, required, display_order) VALUES
  (344, 200133, 'try contains risky code', 'try, risky, may fail', 1, TRUE, 1),
  (345, 200133, 'except handles specific errors', 'except, catch, valueerror, specific, handle', 2, TRUE, 2),
  (346, 200133, 'else runs when no error occurred', 'else, no exception, no error', 1, TRUE, 3),
  (347, 200133, 'finally always runs', 'finally, always, cleanup, clean up, close', 2, TRUE, 4);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200133, 2);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200134, 'TECHNICAL_INTERVIEW', 'MEDIUM', 'TEXT', 'Decorators', 'What is a decorator in Python and how do you write one?', NULL, 'A decorator takes a function and returns a new function that adds behaviour before or after the original. You apply it with the @name syntax. Inside, define a wrapper that accepts *args and **kwargs and use functools.wraps to keep the original name and docstring. Common uses are logging, timing, caching and access control.', TRUE);
INSERT INTO interview_rubric_concepts (id, question_id, name, keywords, weight, required, display_order) VALUES
  (348, 200134, 'A function that wraps another function', 'wraps, wrapper, takes a function, higher-order, function that', 2, TRUE, 1),
  (349, 200134, 'Uses the @ syntax', '@, syntax, applied', 1, TRUE, 2),
  (350, 200134, 'Preserves metadata with functools.wraps', 'functools.wraps, wraps, metadata, __name__', 1, TRUE, 3),
  (351, 200134, 'Typical uses', 'logging, timing, authentication, caching, retry', 2, FALSE, 4);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200134, 2);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200135, 'TECHNICAL_INTERVIEW', 'MEDIUM', 'TEXT', 'Iterators', 'What is the difference between a generator and a list? When would you use a generator?', NULL, 'A list holds all items in memory at once, while a generator yields one item at a time and keeps only its state. Generators are ideal for large or streaming data, such as reading a big file line by line. A generator can be iterated only once.', TRUE);
INSERT INTO interview_rubric_concepts (id, question_id, name, keywords, weight, required, display_order) VALUES
  (352, 200135, 'Generators produce values lazily', 'lazy, lazily, one at a time, on demand, yield', 2, TRUE, 1),
  (353, 200135, 'Lists store everything in memory', 'memory, stores all, in memory, whole list', 2, TRUE, 2),
  (354, 200135, 'Generators can be consumed once', 'once, exhaust, single pass, consumed', 1, TRUE, 3),
  (355, 200135, 'Use for large or infinite data', 'large, big file, stream, infinite, pipeline', 2, FALSE, 4);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200135, 2);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200136, 'TECHNICAL_INTERVIEW', 'MEDIUM', 'TEXT', 'OOP', 'Explain classes, objects, __init__ and inheritance in Python with a short example.', NULL, 'A class defines attributes and methods. Creating an instance calls __init__, which sets up the object using self. A subclass inherits from a parent class, can override its methods and calls super().__init__() to reuse the parent''s setup.', TRUE);
INSERT INTO interview_rubric_concepts (id, question_id, name, keywords, weight, required, display_order) VALUES
  (356, 200136, 'A class is a blueprint, an object is an instance', 'blueprint, instance, object, class', 2, TRUE, 1),
  (357, 200136, '__init__ initialises the object', '__init__, constructor, initial, self', 2, TRUE, 2),
  (358, 200136, 'Inheritance and super()', 'inherit, super(), subclass, parent, base class', 2, TRUE, 3),
  (359, 200136, 'Method overriding or dunder methods', 'overrid, __str__, __repr__, dunder, polymorph', 1, FALSE, 4);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200136, 2);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200137, 'TECHNICAL_INTERVIEW', 'MEDIUM', 'TEXT', 'Copying', 'What is the difference between a shallow copy and a deep copy?', NULL, 'A shallow copy creates a new container but the elements still refer to the same nested objects. A deep copy (copy.deepcopy) recursively copies nested objects, so the copy is fully independent. This matters for lists of lists and objects that contain other mutable objects.', TRUE);
INSERT INTO interview_rubric_concepts (id, question_id, name, keywords, weight, required, display_order) VALUES
  (360, 200137, 'Shallow copy copies only the outer container', 'shallow, outer, top-level, top level, copy.copy', 2, TRUE, 1),
  (361, 200137, 'Nested objects are shared', 'share, same nested, reference, inner', 2, TRUE, 2),
  (362, 200137, 'Deep copy copies everything recursively', 'deep, deepcopy, recursive, independent', 2, TRUE, 3),
  (363, 200137, 'Example with nested lists', 'nested list, list of lists, example, [[', 1, FALSE, 4);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200137, 2);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200138, 'TECHNICAL_INTERVIEW', 'MEDIUM', 'TEXT', 'Tooling', 'How do you manage project dependencies in Python?', NULL, 'Create an isolated virtual environment for each project with venv, install packages with pip and record exact versions in requirements.txt or a lock file (for example with Poetry or pip-tools). This keeps projects from conflicting and makes the setup reproducible for teammates and deployments.', TRUE);
INSERT INTO interview_rubric_concepts (id, question_id, name, keywords, weight, required, display_order) VALUES
  (364, 200138, 'Virtual environments', 'venv, virtualenv, virtual environment, isolat', 2, TRUE, 1),
  (365, 200138, 'pip installs packages', 'pip, install, pypi, package', 1, TRUE, 2),
  (366, 200138, 'requirements file or lock file', 'requirements.txt, pyproject, poetry, lock, pin, version', 2, TRUE, 3),
  (367, 200138, 'Reproducible setup', 'reproduc, same versions, team, deploy', 1, FALSE, 4);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200138, 2);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200139, 'TECHNICAL_INTERVIEW', 'HARD', 'TEXT', 'Concurrency', 'Explain the GIL and how you would choose between threading, multiprocessing and asyncio.', NULL, 'In CPython the GIL lets only one thread execute Python bytecode at a time, so threads do not speed up CPU-bound work. Use threads or asyncio for I/O-bound work such as network calls, where waiting dominates. Use multiprocessing for CPU-bound tasks so each process has its own interpreter and can use another core.', TRUE);
INSERT INTO interview_rubric_concepts (id, question_id, name, keywords, weight, required, display_order) VALUES
  (368, 200139, 'GIL allows one thread to run bytecode at a time', 'gil, global interpreter lock, one thread', 2, TRUE, 1),
  (369, 200139, 'Threads suit I/O-bound work', 'i/o, io-bound, network, waiting, threading', 2, TRUE, 2),
  (370, 200139, 'Multiprocessing for CPU-bound work', 'multiprocessing, cpu-bound, cpu bound, processes, cores', 2, TRUE, 3),
  (371, 200139, 'asyncio for many concurrent I/O tasks', 'asyncio, event loop, async, await, coroutine', 1, TRUE, 4);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200139, 2);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200140, 'TECHNICAL_INTERVIEW', 'HARD', 'TEXT', 'Memory Management', 'How does Python manage memory?', NULL, 'CPython keeps a reference count for every object and frees it when the count reaches zero. Because reference counting cannot free cycles, a cyclic garbage collector also runs periodically. Memory comes from a private heap managed by the interpreter. Tools such as tracemalloc help find leaks.', TRUE);
INSERT INTO interview_rubric_concepts (id, question_id, name, keywords, weight, required, display_order) VALUES
  (372, 200140, 'Reference counting', 'reference count, refcount, count of references', 2, TRUE, 1),
  (373, 200140, 'Cyclic garbage collector', 'cycl, circular, garbage collector, gc module', 2, TRUE, 2),
  (374, 200140, 'Private heap and allocator', 'private heap, allocator, pymalloc, memory manager', 1, TRUE, 3),
  (375, 200140, 'Leaks and tools', 'leak, tracemalloc, weakref, __del__', 1, FALSE, 4);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200140, 2);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200141, 'TECHNICAL_INTERVIEW', 'HARD', 'TEXT', 'Context Managers', 'What is a context manager and how would you create your own?', NULL, 'A context manager guarantees cleanup even if an error occurs. Implement __enter__ and __exit__ in a class, or write a generator with a single yield and decorate it with contextlib.contextmanager. Typical uses are files, locks and database connections.', TRUE);
INSERT INTO interview_rubric_concepts (id, question_id, name, keywords, weight, required, display_order) VALUES
  (376, 200141, 'Manages setup and cleanup with the with statement', 'with statement, with, setup, cleanup, resource', 2, TRUE, 1),
  (377, 200141, '__enter__ and __exit__ methods', '__enter__, __exit__', 2, TRUE, 2),
  (378, 200141, 'contextlib.contextmanager decorator', 'contextlib, @contextmanager, yield', 1, TRUE, 3),
  (379, 200141, 'Examples', 'file, lock, database, connection, transaction', 1, FALSE, 4);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200141, 2);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200142, 'TECHNICAL_INTERVIEW', 'HARD', 'TEXT', 'Performance', 'A Python function is too slow. How would you find and fix the problem?', NULL, 'Measure with cProfile or timeit to find the real hotspot. Then improve the algorithm or data structure, for example replacing list lookups with a set or dictionary. Add caching with functools.lru_cache, use NumPy for numeric work, and only then consider parallelism or compiled extensions.', TRUE);
INSERT INTO interview_rubric_concepts (id, question_id, name, keywords, weight, required, display_order) VALUES
  (380, 200142, 'Measure first with a profiler', 'profil, cprofile, timeit, measure, benchmark', 2, TRUE, 1),
  (381, 200142, 'Improve the algorithm or data structure', 'algorithm, complexity, data structure, set, dict, big o', 2, TRUE, 2),
  (382, 200142, 'Caching or vectorisation', 'lru_cache, cache, memoiz, numpy, vectoriz', 1, TRUE, 3),
  (383, 200142, 'Use parallelism where appropriate', 'multiprocessing, async, parallel, cython', 1, FALSE, 4);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200142, 2);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200143, 'TECHNICAL_INTERVIEW', 'HARD', 'TEXT', 'OOP', 'Explain Python''s method resolution order and how super() behaves with multiple inheritance.', NULL, 'Python computes a method resolution order with the C3 linearisation algorithm, which keeps the order of base classes and puts each class before its parents. super() does not simply mean the parent: it delegates to the next class in the MRO, which makes cooperative multiple inheritance and the diamond problem work. You can inspect it with ClassName.__mro__.', TRUE);
INSERT INTO interview_rubric_concepts (id, question_id, name, keywords, weight, required, display_order) VALUES
  (384, 200143, 'MRO decides the lookup order', 'mro, method resolution order, lookup order', 2, TRUE, 1),
  (385, 200143, 'C3 linearisation', 'c3, linearization, linearisation', 2, TRUE, 2),
  (386, 200143, 'super() follows the MRO', 'super(), next class, follows the mro, cooperative', 2, TRUE, 3),
  (387, 200143, 'Diamond problem', 'diamond, multiple inheritance, __mro__', 1, FALSE, 4);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200143, 2);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200144, 'TECHNICAL_INTERVIEW', 'EASY', 'TEXT', 'Software Process', 'What is the difference between SDLC and STLC?', NULL, 'SDLC describes every phase of building software: requirements, design, development, testing, deployment and maintenance. STLC is the testing-specific process inside it: requirement analysis, test planning, test case design, environment setup, execution and closure. Testing should start early, in parallel with development.', TRUE);
INSERT INTO interview_rubric_concepts (id, question_id, name, keywords, weight, required, display_order) VALUES
  (388, 200144, 'SDLC covers the whole software development process', 'sdlc, development life cycle, development lifecycle, whole process', 2, TRUE, 1),
  (389, 200144, 'STLC covers the testing activities', 'stlc, test life cycle, testing life cycle, testing activit', 2, TRUE, 2),
  (390, 200144, 'Phases of each', 'requirement, design, planning, execution, closure, test case', 2, TRUE, 3),
  (391, 200144, 'Testing runs alongside development', 'parallel, alongside, early, shift left', 1, FALSE, 4);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200144, 5);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200145, 'TECHNICAL_INTERVIEW', 'EASY', 'TEXT', 'Test Design', 'What is a test case and what makes a good one?', NULL, 'A test case describes how to verify one behaviour: ID, preconditions, steps, test data and expected result. Good test cases are clear, independent, repeatable, traceable to a requirement and cover both positive and negative situations, including boundaries.', TRUE);
INSERT INTO interview_rubric_concepts (id, question_id, name, keywords, weight, required, display_order) VALUES
  (392, 200145, 'Contains ID, steps, data and expected result', 'steps, expected result, precondition, test data, test id', 2, TRUE, 1),
  (393, 200145, 'Clear and unambiguous', 'clear, simple, unambiguous, understand', 2, TRUE, 2),
  (394, 200145, 'Independent and repeatable', 'independent, repeatable, reproduc', 2, TRUE, 3),
  (395, 200145, 'Covers positive and negative paths', 'negative, positive, edge, boundary', 1, FALSE, 4);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200145, 5);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200146, 'TECHNICAL_INTERVIEW', 'EASY', 'TEXT', 'Defects', 'What is the difference between severity and priority? Give an example.', NULL, 'Severity describes how badly a defect affects the system and is usually set by the tester. Priority describes how soon it should be fixed and is set by the business. A typo in the company name on the home page has low severity but high priority, while a crash in a rarely used feature may be high severity but low priority.', TRUE);
INSERT INTO interview_rubric_concepts (id, question_id, name, keywords, weight, required, display_order) VALUES
  (396, 200146, 'Severity is technical impact', 'severity, impact, how serious, system', 2, TRUE, 1),
  (397, 200146, 'Priority is urgency of the fix', 'priority, urgency, how soon, business', 2, TRUE, 2),
  (398, 200146, 'Different decision makers', 'tester, product owner, business, manager', 1, TRUE, 3),
  (399, 200146, 'Example', 'for example, e.g., logo, typo, crash, rarely used', 2, TRUE, 4);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200146, 5);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200147, 'TECHNICAL_INTERVIEW', 'EASY', 'TEXT', 'Types of Testing', 'What is regression testing and when do you run it?', NULL, 'Regression testing confirms that new changes such as features or bug fixes did not break existing functionality. It runs after every significant change and before releases. Because it is repeated often it is a prime candidate for automation, and tests are chosen by risk and impact.', TRUE);
INSERT INTO interview_rubric_concepts (id, question_id, name, keywords, weight, required, display_order) VALUES
  (400, 200147, 'Verifies existing features still work', 'existing, still work, not broken, previous', 2, TRUE, 1),
  (401, 200147, 'Run after changes', 'after, change, bug fix, new feature, release, code change', 2, TRUE, 2),
  (402, 200147, 'Good candidate for automation', 'automat, repeat, suite', 2, TRUE, 3),
  (403, 200147, 'Select tests by risk', 'risk, critical, prioriti, impact', 1, FALSE, 4);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200147, 5);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200148, 'TECHNICAL_INTERVIEW', 'EASY', 'TEXT', 'Defects', 'Describe the bug life cycle.', NULL, 'A bug starts as New, is assigned to a developer, gets Fixed and is then retested. If the fix works it is Verified and Closed, if not it is Reopened. A bug can also be Rejected (not a bug), Duplicate or Deferred to a later release.', TRUE);
INSERT INTO interview_rubric_concepts (id, question_id, name, keywords, weight, required, display_order) VALUES
  (404, 200148, 'New and Assigned', 'new, open, assigned', 2, TRUE, 1),
  (405, 200148, 'Fixed by the developer', 'fixed, resolved, developer', 1, TRUE, 2),
