INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200149, 'TECHNICAL_INTERVIEW', 'MEDIUM', 'TEXT', 'Test Techniques', 'Explain black-box, white-box and grey-box testing.', NULL, 'Black-box testing checks behaviour against requirements without looking at the code. White-box testing uses knowledge of the code, for example to cover statements and branches. Grey-box testing combines both, with partial knowledge such as the database schema or API design.', TRUE);
INSERT INTO interview_rubric_concepts (id, question_id, name, keywords, weight, required, display_order) VALUES
  (408, 200149, 'Black-box tests behaviour without code knowledge', 'black-box, black box, without knowledge, requirements, inputs and outputs', 2, TRUE, 1),
  (409, 200149, 'White-box uses internal code knowledge', 'white-box, white box, internal, code, statement coverage, branch', 2, TRUE, 2),
  (410, 200149, 'Grey-box is a combination', 'grey-box, grey box, gray, partial knowledge, combination', 2, TRUE, 3),
  (411, 200149, 'Typical examples', 'unit test, functional test, api, database', 1, FALSE, 4);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200149, 5);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200150, 'TECHNICAL_INTERVIEW', 'MEDIUM', 'TEXT', 'Test Design', 'Explain boundary value analysis and equivalence partitioning with an example.', NULL, 'Equivalence partitioning divides inputs into groups that should behave the same and tests one value from each. Boundary value analysis tests at the edges, because defects cluster there. For an age field that accepts 18 to 60, test 17, 18, 19, 59, 60 and 61 plus a typical value like 30.', TRUE);
INSERT INTO interview_rubric_concepts (id, question_id, name, keywords, weight, required, display_order) VALUES
  (412, 200150, 'Equivalence partitioning groups similar inputs', 'equivalence, partition, group', 2, TRUE, 1),
  (413, 200150, 'Test one value per partition', 'one value, representative, each partition', 1, TRUE, 2),
  (414, 200150, 'Boundary values around limits', 'boundar, edge, minimum, maximum, just below', 2, TRUE, 3),
  (415, 200150, 'Worked example', 'for example, e.g., age, 18, 60, 1 to 100', 2, TRUE, 4);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200150, 5);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200151, 'TECHNICAL_INTERVIEW', 'MEDIUM', 'TEXT', 'Test Types', 'What is the difference between smoke testing and sanity testing?', NULL, 'Smoke testing is a quick, broad check of the critical functions to decide whether a new build is stable enough for deeper testing. Sanity testing is narrow and focused on verifying that a particular change or bug fix works and did not break related behaviour.', TRUE);
INSERT INTO interview_rubric_concepts (id, question_id, name, keywords, weight, required, display_order) VALUES
  (416, 200151, 'Smoke checks the stability of a new build', 'smoke, build, stable, critical function', 2, TRUE, 1),
  (417, 200151, 'Sanity checks a specific change', 'sanity, specific, bug fix, small change, narrow', 2, TRUE, 2),
  (418, 200151, 'Smoke is broad and shallow', 'broad, shallow, wide', 1, TRUE, 3),
  (419, 200151, 'Decision after the result', 'reject, proceed, further testing', 1, FALSE, 4);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200151, 5);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200152, 'TECHNICAL_INTERVIEW', 'MEDIUM', 'TEXT', 'Test Automation', 'How do you decide which test cases to automate?', NULL, 'Automate tests that run often, are stable and deterministic, such as regression and smoke suites, and cover critical business flows or data-driven cases. Do not automate exploratory, one-off or constantly changing tests. Weigh the effort and maintenance cost against the time saved.', TRUE);
INSERT INTO interview_rubric_concepts (id, question_id, name, keywords, weight, required, display_order) VALUES
  (420, 200152, 'Repetitive and stable tests', 'repetitive, repeat, stable, regression', 2, TRUE, 1),
  (421, 200152, 'High-risk and critical flows', 'critical, high risk, high-risk, business', 2, TRUE, 2),
  (422, 200152, 'Poor candidates are exploratory or changing tests', 'exploratory, usability, frequently changing, one-time, one time', 2, TRUE, 3),
  (423, 200152, 'Return on investment', 'roi, cost, effort, maintenance', 1, FALSE, 4);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200152, 5);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200153, 'TECHNICAL_INTERVIEW', 'MEDIUM', 'TEXT', 'Selenium', 'How does Selenium WebDriver work and how do you make scripts reliable?', NULL, 'WebDriver sends commands to the browser through a browser driver. Locate elements with stable locators such as ids or CSS selectors, use explicit waits (WebDriverWait with ExpectedConditions) instead of fixed sleeps, and organise code with the Page Object Model to keep tests maintainable.', TRUE);
INSERT INTO interview_rubric_concepts (id, question_id, name, keywords, weight, required, display_order) VALUES
  (424, 200153, 'Controls the browser through drivers', 'driver, browser, chromedriver, webdriver', 2, TRUE, 1),
  (425, 200153, 'Locators', 'locator, id, xpath, css selector, by.', 2, TRUE, 2),
  (426, 200153, 'Explicit waits instead of sleeps', 'explicit wait, webdriverwait, expectedconditions, implicit, avoid thread.sleep', 2, TRUE, 3),
  (427, 200153, 'Page Object Model', 'page object, pom', 1, FALSE, 4);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200153, 5);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200154, 'TECHNICAL_INTERVIEW', 'HARD', 'TEXT', 'Automation Framework', 'How would you design a test automation framework?', NULL, 'Build a layered framework: page objects for UI, reusable utilities, externalised test data and configuration, a test runner such as TestNG or JUnit, rich reporting with screenshots on failure, and integration with a CI pipeline that can run tests in parallel.', TRUE);
INSERT INTO interview_rubric_concepts (id, question_id, name, keywords, weight, required, display_order) VALUES
  (428, 200154, 'Layered structure with Page Objects', 'page object, pom, layer, structure, modular', 2, TRUE, 1),
  (429, 200154, 'Data-driven and reusable utilities', 'data-driven, data driven, test data, utility, reusable', 2, TRUE, 2),
  (430, 200154, 'Reporting and logging', 'report, log, screenshot, allure, extent', 1, TRUE, 3),
  (431, 200154, 'CI integration and parallel runs', 'ci, jenkins, github actions, pipeline, parallel', 2, TRUE, 4),
  (432, 200154, 'Test runner such as TestNG or JUnit', 'testng, junit, pytest, runner', 1, FALSE, 5);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200154, 5);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200155, 'TECHNICAL_INTERVIEW', 'HARD', 'TEXT', 'Test Automation', 'How do you handle flaky automated tests?', NULL, 'Investigate why the test is unstable: usually timing and synchronisation, shared test data or unstable environments. Replace fixed sleeps with explicit waits, make each test independent with its own data, and use retries or quarantine only as a temporary measure while tracking the fix.', TRUE);
INSERT INTO interview_rubric_concepts (id, question_id, name, keywords, weight, required, display_order) VALUES
  (433, 200155, 'Find the root cause', 'root cause, investigat, analy, reproduce', 2, TRUE, 1),
  (434, 200155, 'Fix waits and synchronisation', 'wait, synchroni, timing, sleep', 2, TRUE, 2),
  (435, 200155, 'Isolate test data and environments', 'isolat, test data, shared state, independent, environment', 2, TRUE, 3),
  (436, 200155, 'Quarantine and retry sparingly', 'quarantine, retry, rerun, track', 1, FALSE, 4);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200155, 5);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200156, 'TECHNICAL_INTERVIEW', 'HARD', 'TEXT', 'Performance Testing', 'How would you approach performance testing a web application?', NULL, 'Start with goals and a realistic workload. Run load, stress, spike and endurance tests with a tool such as JMeter, Gatling or k6, and monitor response time percentiles, throughput, error rate and resource usage. Analyse bottlenecks, fix them and re-test.', TRUE);
INSERT INTO interview_rubric_concepts (id, question_id, name, keywords, weight, required, display_order) VALUES
  (437, 200156, 'Define goals and workload', 'goal, requirement, workload, user load, sla, scenario', 2, TRUE, 1),
  (438, 200156, 'Load, stress and endurance tests', 'load, stress, spike, endurance, soak', 2, TRUE, 2),
  (439, 200156, 'Metrics', 'response time, throughput, error rate, cpu, memory, percentile', 2, TRUE, 3),
  (440, 200156, 'Tools and analysis', 'jmeter, gatling, k6, bottleneck', 1, FALSE, 4);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200156, 5);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200157, 'TECHNICAL_INTERVIEW', 'HARD', 'TEXT', 'API Testing', 'How do you test a REST API thoroughly?', NULL, 'Test each endpoint with valid and invalid input and check status codes, response bodies, schema and headers. Test authentication and authorisation, including 401 and 403 cases, plus boundaries and error handling. Use Postman for exploration and automate regression checks with Newman or REST Assured in the pipeline.', TRUE);
INSERT INTO interview_rubric_concepts (id, question_id, name, keywords, weight, required, display_order) VALUES
  (441, 200157, 'Functional and negative tests', 'status code, positive, negative, invalid, validation', 2, TRUE, 1),
  (442, 200157, 'Validate response body, schema and headers', 'body, schema, header, json', 2, TRUE, 2),
  (443, 200157, 'Authentication and authorisation', 'authentication, authorization, authorisation, token, 401, 403', 2, TRUE, 3),
  (444, 200157, 'Tools and automation', 'postman, rest assured, restassured, newman, automat', 1, FALSE, 4);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200157, 5);
INSERT INTO interview_questions (id, round_type, difficulty_level, question_type, topic, question_text, guidance, explanation, active) VALUES (200158, 'TECHNICAL_INTERVIEW', 'HARD', 'TEXT', 'Test Strategy', 'How do you decide whether a release is ready, and how does risk-based testing help?', NULL, 'Test the highest-risk and highest-impact areas first. Release readiness is judged against agreed exit criteria such as pass rate, coverage and no open blocker or critical defects. Present the results and the residual risk clearly so stakeholders can make the go or no-go decision.', TRUE);
INSERT INTO interview_rubric_concepts (id, question_id, name, keywords, weight, required, display_order) VALUES
  (445, 200158, 'Risk-based prioritisation', 'risk, prioriti, critical, impact', 2, TRUE, 1),
  (446, 200158, 'Exit criteria and metrics', 'exit criteria, pass rate, coverage, defect', 2, TRUE, 2),
  (447, 200158, 'Open defects judged by severity', 'severity, blocker, critical defect, known issue', 2, TRUE, 3),
  (448, 200158, 'Communicate to stakeholders', 'stakeholder, report, sign-off, go/no-go, go no-go', 1, FALSE, 4);
INSERT INTO interview_question_roles (question_id, role_id) VALUES (200158, 5);
